# Stories for albums 201–250 (long format agreed with the owner: three paragraphs + a listening tip,
# ~250 words, three picks). Original Hebrew; facts checked on the web, uncertain ones softened.
# Used by tools/batches/build_201_250.py; later edits: python3 tools/apply_stories.py stories_201_250
STORIES = {}
def add(n, story, picks): STORIES[n] = {'story': story, 'picks': picks}

add(202, [
'''בחודשים האחרונים של הביטלס, פול מקרטני הסתגר בביתו בלונדון ובחווה שלו בסקוטלנד, עם רשמקול ביתי פשוט, והקליט לבד שירים חדשים ורעיונות קטנים. הוא ניגן בעצמו על כל הכלים, ואשתו לינדה שרה איתו הרמוניות. McCartney יצא באפריל 1970, ויחד איתו הודעה לעיתונות שבה מקרטני הבהיר שהוא לא עובד עוד עם הביטלס. לרבים זה היה הרגע שבו התברר שהלהקה נגמרה.''',
'''זה אלבום ביתי, רגוע וכמעט לא גמור: חלק מהשירים הם סקיצות קצרות, חלק קטעים אינסטרומנטליים, ורוב ההקלטות נשמעות כאילו נעשו במטבח. The Lovely Linda נמשך פחות מדקה ונקטע בצחוק, Junk ו־Every Night הם שירים אקוסטיים שקטים ויפים, ו־Momma Miss America הוא ג׳אם של פסנתר ותופים. ובאמצע כל זה מגיע Maybe I'm Amazed, שיר אהבה גדול ללינדה, עם פסנתר, גיטרה חשמלית וקול מלא תשוקה, אחד השירים הטובים שמקרטני כתב אי פעם.''',
'''המבקרים היו מאוכזבים, וחלק מחבריו לביטלס כעסו על העיתוי. אבל האלבום הגיע למקום הראשון באמריקה, ועם השנים הוא הוערך מחדש כאחד מאלבומי ה"עשה זאת בעצמך" הראשונים של כוכב גדול: הקלטה ביתית, בלי אולפן ובלי מפיק. באותה שנה ג׳ון לנון וג׳ורג׳ הריסון הוציאו את אלבומי הסולו שלהם (אלבומים 183 ו־196), וכל אחד מהשלושה נשמע אחרת לגמרי.''',
'''שמעו את Maybe I'm Amazed ואחריו את Every Night: אותו אדם, אותו חדר, ושני קצוות של רגש. אחר כך נסו להשוות לאלבום של לנון (אלבום 183): שני חברים לשעבר, אחד צועק את הכאב, ואחד מתכנס בשקט בבית עם המשפחה.''',
], [
("Maybe I'm Amazed", 'שיר אהבה גדול ללינדה, עם פסנתר, גיטרה וקול מלא תשוקה. מהשירים הטובים של מקרטני.'),
('Every Night', 'שיר אקוסטי שקט על ימים קשים ועל אהבה שמצילה, עם מלודיה פשוטה ויפה.'),
('Junk', 'שיר רך ומלנכולי על חפצים ישנים וזיכרונות, שנכתב עוד בימי הביטלס.'),
])

add(203, [
'''קרלוס סנטנה, גיטריסט צעיר ממקסיקו שגדל בסן פרנסיסקו, הקים להקה ששילבה רוק ובלוז עם כלי הקשה לטיניים: קונגות, טימבלס ומקצבים קובניים. ההופעה שלהם בוודסטוק ב־1969, עוד לפני שהקהל הכיר אותם, הפכה לאגדה. Abraxas, האלבום השני, יצא בספטמבר 1970, ועל העטיפה ציור צבעוני של האמן מאטי קלארוויין, שצייר גם את העטיפה של Bitches Brew (אלבום 177).''',
'''הגיטרה של סנטנה שרה: צליל חם ומתמשך שנשמע כמעט כמו קול אנושי, מעל אורגן, בס וכלי הקשה סוערים. Black Magic Woman, שיר של פיטר גרין מפליטווד מק, מתחבר ל־Gypsy Queen, יצירה של הגיטריסט ההונגרי גאבור סאבו, ויוצר מסע אחד של מיסטיקה ולהט. Oye Como Va, שיר של מלך המאמבו טיטו פואנטה, הופך לרוק לטיני רוקד, ו־Samba Pa Ti הוא בלדה אינסטרומנטלית איטית ויפהפה, שבה הגיטרה מספרת סיפור אהבה בלי מילים. כלי ההקשה של חוסה צ׳פיטו אריאס ומייקל קאראבלו, והאורגן של גרג רולי, יוצרים בסיס קצבי שכמעט אי אפשר לשבת מולו בשקט.''',
'''Abraxas הגיע למקום הראשון באמריקה ונשאר שם שש שבועות, ונמכר במיליונים. הוא הכניס את הרוק הלטיני למיינסטרים, והראה שמקצבים מאמריקה הלטינית יכולים להשתלב ברוק באותה טבעיות כמו הבלוז. סנטנה המשיך להקליט ולהופיע במשך עשרות שנים, וב־1999 חזר לראש המצעדים עם האלבום Supernatural. ב־Abraxas אפשר לשמוע את סנטנה בשיא הכוח של ההרכב המקורי, שבו כל נגן הביא עולם מוזיקלי משלו.''',
'''שמעו את Samba Pa Ti בשקט, ותקשיבו איך הגיטרה מתחילה בלחישה ונבנית לאט לשיא. אחר כך את Oye Como Va, ונסו לא לזוז.''',
], [
('Black Magic Woman / Gypsy Queen', 'שני שירים שמתחברים למסע אחד של גיטרה מיסטית וכלי הקשה לוהטים.'),
('Oye Como Va', 'שיר של טיטו פואנטה בגרסת רוק לטיני, עם אורגן מדבק וגיטרה שרה.'),
('Samba Pa Ti', 'בלדה אינסטרומנטלית יפהפייה: גיטרה שמספרת סיפור אהבה בלי מילים.'),
])

add(204, [
'''סיד בארט היה הכותב, הזמר והגיטריסט של פינק פלויד באלבום הבכורה שלהם (אלבום 89), אבל ב־1968, כשהתנהגותו הפכה לבלתי צפויה, כנראה גם בגלל שימוש כבד ב־LSD ובעיות נפשיות, חבריו ללהקה נאלצו להיפרד ממנו. The Madcap Laughs, אלבום הסולו הראשון שלו, הוקלט לאורך יותר משנה עם כמה מפיקים, ובסוף בעזרת דייוויד גילמור ורוג׳ר ווטרס, שני חבריו מפינק פלויד. הוא יצא בתחילת 1970.''',
'''זה אלבום שביר, מוזר ויפה: לרוב רק סיד וגיטרה אקוסטית, לפעמים עם ליווי דליל של תופים או בס. Terrapin פותח בבלוז איטי וחלומי על דגים ועל צבים, Octopus הוא שיר קצבי עם מילים מטורפות ומשעשעות, ו־Golden Hair הוא לחן לשיר של הסופר האירי ג׳יימס ג׳ויס. בחלק מהשירים נשמעות התחלות שנכשלו, טעויות וקולות של סיד מדבר עם האולפן, והמפיקים השאירו אותם בכוונה, כמו חלון לראש שלו. בשניים מהשירים מלווים אותו חברי סופט מאשין (אלבום 194).''',
'''בארט הקליט עוד אלבום אחד, ואז נסוג מעולם המוזיקה לגמרי וחי בשקט בקיימברידג׳ עד מותו ב־2006. אבל השירים שלו, תמימים, מבולבלים וכנים, הפכו אותו לאגדה ולהשראה עבור מוזיקאים רבים, מדייוויד בואי ועד להקות אינדי. פינק פלויד עצמם כתבו עליו שירים, בהם Shine On You Crazy Diamond. שם האלבום, "המטורף צוחק", נשמע היום עצוב, אבל יש בו גם את ההומור והמשחקיות שתמיד היו חלק ממנו.''',
'''זה לא אלבום קל, והוא לא מושלם. שמעו אותו כמו שמסתכלים על ציורים של ילד מחונן: Terrapin ו־Octopus קודם, ואז Dark Globe, שבו הקול שלו נשבר ושואל "האם תתגעגעו אליי?".''',
], [
('Terrapin', 'הפותח: בלוז איטי וחלומי על עולם מתחת למים, עם גיטרה אקוסטית וקול שקט.'),
('Octopus', 'שיר קצבי ומשעשע עם מילים מטורפות, הרגע הכי "פופי" באלבום.'),
('Dark Globe', 'שיר קצר ושבור, שבו סיד שואל אם יתגעגעו אליו.'),
])

add(205, [
'''ג׳ת׳רו טאל התחילו בסוף שנות השישים כלהקת בלוז בריטית, אבל הסולן שלהם, איאן אנדרסון, עם חליל, זקן ומעיל ישן, עמד על רגל אחת על הבמה ונתן להם מראה ייחודי. עד 1971 הם כבר שילבו רוק כבד, פולק ומוזיקה קלאסית. Aqualung, האלבום הרביעי שלהם, יצא במרץ 1971, והפך להצלחה הגדולה שלהם.''',
'''שיר הנושא נפתח באחד הריפים המפורסמים של הרוק ומתאר קבצן זקן ועלוב, שיושב על ספסל בפארק ומסתכל על ילדות קטנות. זה דיוקן קשה ואכזרי, ובאמצע הוא מתחלף לקטע רך ואקוסטי ולסולו גיטרה של מרטין באר. Cross-Eyed Mary מספר על נערת רחוב, Locomotive Breath הוא שיר רוק דוהר עם פסנתר וחליל על אדם שחייו יוצאים משליטה כמו רכבת, ו־Wind-Up סוגר את האלבום בביקורת חריפה על דת ממוסדת. בין השירים הכבדים יש קטעים אקוסטיים קצרים, כמו Cheap Day Return ו־Mother Goose, עם גיטרה, חליל ודמיון.''',
'''הצד השני של התקליט עוסק באלוהים ובכנסייה, ורבים ראו באלבום "אלבום קונספט", אף שאנדרסון עצמו התעקש שזו רק אסופת שירים. כך או כך, Aqualung מכר מיליוני עותקים, והפך את ג׳ת׳רו טאל לאחת הלהקות הגדולות של שנות השבעים. הריף של שיר הנושא, והחליל הדוהר של Locomotive Breath, נשמעים עד היום בכל תחנת רדיו של רוק קלאסי.''',
'''שמעו את Aqualung עד הסוף ושימו לב למעברים בין החלק הכבד לחלק האקוסטי. אחר כך את Locomotive Breath, ונסו לספור כמה פעמים החליל מצליח להיכנס בין הגיטרות.''',
], [
('Aqualung', 'ריף מפורסם ודיוקן קשה של קבצן זקן, עם מעבר אקוסטי וסולו גיטרה.'),
('Locomotive Breath', 'פסנתר דוהר, חליל וגיטרה: שיר על חיים שיוצאים משליטה כמו רכבת.'),
('Cross-Eyed Mary', 'שיר רוק כבד עם חליל, על נערת רחוב בלונדון.'),
])

add(206, [
'''דייוויד קרוסבי, חבר בבירדס ובקרוסבי, סטילס, נאש ויאנג (אלבומים 57 ו־184), היה במצב קשה ב־1970: בת הזוג שלו נהרגה בתאונת דרכים שנה קודם, והוא בילה לילות ארוכים באולפן בסן פרנסיסקו, מוקף בחברים. לאלבום הסולו הראשון שלו, שיצא בתחילת 1971, הגיעו כמעט כל המוזיקאים של הסצנה: חברי גרייטפול דד וג׳פרסון איירפליין, ג׳וני מיצ׳ל, ניל יאנג וגראהם נאש. הם כינו את עצמם בצחוק "תזמורת הרוקנרול של כדור הארץ".''',
'''התוצאה היא אלבום מרחף, חלומי ועצוב, שנשמע כמו ג׳אם של חברים בשעות הקטנות של הלילה. Music Is Love פותח עם גיטרות אקוסטיות וקולות שחוזרים על משפט אחד פשוט. Cowboy Movie הוא סיפור מערבון ארוך על להקת פורעי חוק, שהוא בעצם משל לקרוסבי, סטילס, נאש ויאנג. Laughing הוא שיר יפהפה עם גיטרת פדל־סטיל של ג׳רי גרסיה, ו־Song with No Words ו־I'd Swear There Was Somebody Here הם קטעים של קולות בלבד, בלי מילים, שנשמעים כמו תפילה או כמו רוחות.''',
'''המבקרים של 1971 זלזלו באלבום וראו בו פינוק של כוכב, אבל הקהל קנה אותו, ובמשך השנים הוא הפך לאלבום אהוב מאוד. היום הוא נחשב לאחד המסמכים היפים של סצנת סן פרנסיסקו ולאחד האלבומים שמבטאים הכי טוב את העצב והחלומות של סוף שנות השישים.''',
'''שמעו את האלבום בשעת לילה, בשקט. Laughing הוא מקום טוב להתחיל, ואז I'd Swear There Was Somebody Here, קטע קצר של קולות שקרוסבי הקליט לבד, ורבים שומעים בו געגוע לבת הזוג שאיבד.''',
], [
('Laughing', 'שיר מרחף ויפהפה עם פדל־סטיל של ג׳רי גרסיה והרמוניות רכות.'),
('Music Is Love', 'הפותח: גיטרות אקוסטיות וקולות של חברים שחוזרים על משפט אחד פשוט.'),
('Cowboy Movie', 'סיפור מערבון ארוך ומחוספס, שהוא בעצם משל על להקה שמתפרקת.'),
])

add(207, [
'''אחרי ההצלחה העצומה של Stand! (אלבום 160) וההופעה בוודסטוק, סליי סטון עבר ללוס אנג׳לס ושקע בסמים, בפרנויה ובמאבקים עם חברי הלהקה, עם חברת התקליטים ועם פעילים פוליטיים שדרשו ממנו להקצין. הוא הקליט את האלבום הבא כמעט לבד, בבית ובאולפן, והקליט שוב ושוב על אותן סלילים עד שהצליל נשחק. There's a Riot Goin' On יצא בסוף 1971.''',
'''זה אלבום עכור, איטי ומסתורי, כמעט ההפך הגמור מהאופטימיות של Stand!. במקום מתופף, בחלק מהשירים מנגנת מכונת תופים פשוטה, אחת הראשונות בשימוש באלבום גדול. הקול של סליי ממלמל, עייף ולפעמים כמעט נבלע במוזיקה. Family Affair הוא שיר רך ומנומנם על משפחה, אהבה וכאב, שהגיע למקום הראשון. Runnin' Away נשמע עליז, אבל המילים מרות, ו־Thank You for Talkin' to Me Africa הוא גרסה איטית ומעוותת ללהיט ישן של הלהקה. שיר הנושא אורכו אפס שניות: שקט מוחלט. גם כאן יש ללהקה רגעים של גרוב נפלא, כמו ב־(You Caught Me) Smilin׳, אבל הכול נשמע רחוק, כאילו דרך דלת סגורה.''',
'''באותה שנה Marvin Gaye שאל "מה קורה?" (אלבום 208), וסליי ענה בשקט מדכא. האלבום נחשב היום לאחד מאבני היסוד של הפאנק האיטי והאפל, והשפיע על פרינס, על מוזיקאי היפ הופ ועל אמני סול עכשוויים. הוא מתעד את הרגע שבו חלום שנות השישים נגמר, מבפנים.''',
'''שמעו את Family Affair ואחריו את Everyday People מ־Stand! (אלבום 160): אותה להקה, שנתיים וחצי בהפרש, ונדמה שעבר עשור. זה אלבום לשמוע בשקט ובריכוז, לא במסיבה.''',
], [
('Family Affair', 'שיר רך ומנומנם על משפחה ואהבה, עם מכונת תופים וקול עייף. מקום ראשון במצעד.'),
("Runnin' Away", 'מנגינה עליזה עם כלי נשיפה ומילים מרות על בריחה מעצמך.'),
("Thank You for Talkin' to Me Africa", 'להיט ישן של הלהקה בגרסה איטית, כבדה ומעוותת, כמו חלום רע.'),
])

add(208, [
'''מרווין גיי היה אחד מכוכבי מוטאון הגדולים, עם להיטים רומנטיים ודואטים עם תמי טרל. אבל בסוף שנות השישים הוא עבר משבר: טרל, שותפתו לשירה, מתה ממחלה, אחיו חזר ממלחמת וייטנאם עם סיפורים קשים, והוא ראה סביבו עוני, אלימות משטרתית, סמים והרס של הסביבה. ב־1970 הוא התחיל לכתוב שירים על כל זה, והפיק אותם בעצמו, למרות שבעל מוטאון, ברי גורדי, חשב שזה לא יימכר. What's Going On יצא במאי 1971.''',
'''זה מחזור שירים, והם זורמים זה לתוך זה בלי הפסקה, כמו יצירה אחת. שיר הנושא נפתח בקולות של מסיבה ובסקסופון רך, ומרווין שואל, כמעט בלחישה, "מה קורה?". Mercy Mercy Me (The Ecology) הוא אחד משירי הפופ הראשונים על זיהום הסביבה, ו־Inner City Blues (Make Me Wanna Holler) מתאר את החיים בשכונות העוני. מתחת לכל זה יש גרוב רך, תופי קונגה, כלי מיתר ובס מתנגן, והקול של מרווין מוקלט בכמה שכבות, ומשוחח עם עצמו.''',
'''גורדי טעה: האלבום הפך להצלחה ענקית, שלושה משיריו הגיעו לעשירייה הראשונה, והוא נחשב היום לאחד מאלבומי הסול הגדולים ואולי לגדול שבהם. הוא שינה את מוטאון והראה שאמן שחור יכול לכתוב אלבום אישי, פוליטי ורוחני, ולא רק סינגלים. סטיבי וונדר ורבים אחרים הלכו בדרך הזאת מיד אחריו.''',
'''שמעו את האלבום ברצף, מההתחלה ועד הסוף, כמו סימפוניה. אחר כך השוו ל־There's a Riot Goin' On (אלבום 207) מאותה שנה: שני אמנים שחורים שמתארים את אמריקה של 1971, אחד בתקווה ובתפילה, ואחד בייאוש.''',
], [
("What's Going On", 'שיר הנושא: שאלה שקטה על מלחמה ואלימות, מעל גרוב רך וסקסופון.'),
('Mercy Mercy Me (The Ecology)', 'אחד משירי הפופ הראשונים על זיהום הסביבה, יפהפה ועצוב.'),
('Inner City Blues (Make Me Wanna Holler)', 'שיר הסיום: גרוב אפל ומהפנט על החיים בשכונות העוני.'),
])

add(209, [
'''יס היו להקה בריטית שחלמה לשלב רוק עם מוזיקה קלאסית, עם הרמוניות קוליות ושירים ארוכים. שני האלבומים הראשונים שלהם לא הצליחו, וחברת התקליטים כמעט ויתרה עליהם. ואז הצטרף סטיב האו, גיטריסט עם סגנון ייחודי, שנע בין רוק, ג׳אז, קאנטרי וגיטרה קלאסית. The Yes Album, שיצא בתחילת 1971, היה הפריצה שלהם. הלהקה הסתגרה בחווה כפרית באנגליה כדי לעבוד על השירים, ושם גיבשה את הסגנון שיוביל אותה בשנים הבאות.''',
'''השירים ארוכים, בנויים מחלקים שונים שמתחלפים זה בזה. Yours Is No Disgrace נפתח בריף גדול ונמשך תשע וחצי דקות של גיטרה, אורגן ובס מנגן. Starship Trooper הוא מסע בשלושה חלקים שמסתיים בקטע גיטרות שחוזר ובונה את עצמו לשיא. I've Seen All Good People מתחיל בהרמוניות אקוסטיות ומשתנה לרוקנרול שמח. ו־The Clap הוא קטע גיטרה אקוסטית סולו, שהאו ניגן בהופעה חיה. הקול הגבוה של ג׳ון אנדרסון והבס החד של כריס סקוויר הם סימני ההיכר של הלהקה.''',
'''The Yes Album הגיע לעשירייה הראשונה בבריטניה, והפך את יס לאחת הלהקות החשובות של הרוק המתקדם. שנה אחר כך הצטרף הקלידן ריק ווייקמן, והלהקה המשיכה לאלבומים שאפתניים עוד יותר (אלבומים 218 ו־250). הצליל של הלהקה, עם הרמוניות קוליות מדויקות, גיטרה מתוחכמת ובס בולט, הפך לסימן ההיכר של הרוק המתקדם הבריטי.''',
'''שמעו את I've Seen All Good People ושימו לב לאמצע, כשההרמוניות האקוסטיות מתחלפות פתאום לרוקנרול. אם אתם אוהבים גיטרה, The Clap הוא שלוש דקות של הנאה טהורה.''',
], [
('Yours Is No Disgrace', 'הפותח: ריף גדול ותשע דקות של מסע, עם גיטרה, אורגן ובס מנגן.'),
("I've Seen All Good People", 'הרמוניות אקוסטיות שמתחלפות לרוקנרול שמח: השיר המוכר של הלהקה.'),
('Starship Trooper', 'מסע בשלושה חלקים שמסתיים בגיטרות שחוזרות ובונות שיא גדול.'),
])

add(210, [
'''הבי ג׳יז, שלושה אחים שנולדו באנגליה וגדלו באוסטרליה, בארי, רובין ומוריס גיב, התפרסמו בסוף שנות השישים בבלדות פופ עם הרמוניות קול צמודות. ב־1969 רובין עזב אחרי ריב, והלהקה כמעט התפרקה, אבל ב־1970 האחים התאחדו. Trafalgar, שיצא בסוף 1971, הוא אחד האלבומים שהקליטו אחרי האיחוד, והעטיפה שלו היא ציור של קרב טרפלגר. האחים כתבו כמעט את כל השירים שלהם בעצמם, וכתבו גם לזמרים אחרים, ובתחילת שנות השבעים כבר נחשבו לכותבים מבוקשים מאוד.''',
'''זה אלבום של בלדות: שקט, רומנטי ומלנכולי, עם כלי מיתר, פסנתר וההרמוניות של שלושת האחים. How Can You Mend a Broken Heart, השיר הפותח, הוא שיר עצוב ורך על לב שבור, שבארי ורובין שרים יחד, והוא הפך ללהיט הראשון שלהם שהגיע למקום הראשון באמריקה. לצידו יש שירים של כל אחד מהאחים: בלדות דרמטיות, שירי אהבה ושירים עם תזמור גדול, כמו Israel ו־Walking Back to Waterloo. הקול הרועד של רובין והקול החם של בארי מתחלפים ומשתלבים.''',
'''Trafalgar שייך לתקופה של הבי ג׳יז לפני הדיסקו, כשהם נחשבו לכותבים של בלדות פופ מלנכוליות. כעבור כמה שנים הם יהפכו לסמל של תקופת הדיסקו, עם Saturday Night Fever. How Can You Mend a Broken Heart בוצע מאוחר יותר על ידי זמרים רבים, ובהם אל גרין, והפך לסטנדרט.''',
'''שמעו את How Can You Mend a Broken Heart בשקט, והקשיבו להרמוניות: שני אחים ששרים כמעט באותו קול. אם אתם מכירים רק את הבי ג׳יז של הדיסקו, תופתעו.''',
], [
('How Can You Mend a Broken Heart', 'בלדה עצובה ורכה על לב שבור, הלהיט הראשון שלהם במקום הראשון באמריקה.'),
('Israel', 'בלדה דרמטית עם תזמור גדול, בקולו החם והעמוק של בארי גיב.'),
('Walking Back to Waterloo', 'שיר מלנכולי עם כלי מיתר וההרמוניות המיוחדות של האחים.'),
])

add(211, [
'''אחרי Tommy (אלבום 145), פיט טאונסנד תכנן פרויקט עוד יותר שאפתני בשם Lifehouse: סרט, אופרת רוק וניסוי חי עם קהל, על עתיד שבו אנשים חיים מול מסכים ומאבדים קשר למוזיקה. הפרויקט היה מסובך מדי, ואיש לא הבין אותו, והוא קרס. The Who לקחו כמה מהשירים הכי טובים שנכתבו לו, והוציאו אותם כאלבום רגיל: Who's Next, שיצא באוגוסט 1971.''',
'''טאונסנד הביא לאלבום סינתיסייזר ואורגן חשמלי, והשתמש בהם בצורה חדשה: דפוסים חוזרים ומנצנצים שנשמעים כמו מכונה חיה. Baba O'Riley נפתח בדפוס כזה, ואז נכנסים הפסנתר, התופים והקול של רוג׳ר דאלטרי, והשיר מסתיים בכינור פרוע. Won't Get Fooled Again הוא שיר של שמונה וחצי דקות על מהפכות שמחליפות שליט אחד באחר, עם אחת הצעקות המפורסמות בתולדות הרוק. Behind Blue Eyes הוא שיר עצוב על "האיש הרע" שאף אחד לא מבין, ו־My Wife, השיר של ג׳ון אנטוויסל, הוא שיר רוק משעשע.''',
'''Who's Next הגיע למקום הראשון בבריטניה, ונחשב בעיני רבים לאלבום הטוב ביותר של The Who. הוא הראה איך אפשר לשלב סינתיסייזרים ברוק בלי לאבד את העוצמה, והשירים שלו הפכו לחלק קבוע מהרדיו, מהסרטים ומהטלוויזיה. המפיק גלין ג׳ונס, שעבד גם עם הסטונס ולד זפלין, עזר ללהקה ללטש את הצליל ולהפוך אותו לגדול, ברור ומלא עוצמה.''',
'''שמעו את Baba O'Riley ואחריו את Won't Get Fooled Again, בקול רם. ואז השוו ל־Live at Leeds (אלבום 193): אותה להקה, שנה אחת בהפרש, עם צליל גדול ומלוטש.''',
], [
("Baba O'Riley", 'דפוס סינתיסייזר מנצנץ, פסנתר ותופים, וסיום של כינור פרוע.'),
("Won't Get Fooled Again", 'שמונה דקות וחצי על מהפכות, עם צעקה מפורסמת לפני הסוף.'),
('Behind Blue Eyes', 'שיר שקט ועצוב על "האיש הרע" שאף אחד לא מבין, שמתפוצץ באמצע.'),
])

add(212, [
'''לפני שהייתה זמרת, קרול קינג הייתה אחת הכותבות המצליחות בניו יורק של שנות השישים. יחד עם בעלה, ג׳רי גופין, היא כתבה להיטים לאחרים, כמו Will You Love Me Tomorrow של השירלז ו־(You Make Me Feel Like) A Natural Woman של אריתה פרנקלין (אלבום 117). אחרי הגירושים היא עברה ללוס אנג׳לס, התחברה לג׳יימס טיילור (אלבום 201) ולג׳וני מיצ׳ל, והתחילה לשיר בעצמה. Tapestry, האלבום השני שלה, יצא בתחילת 1971.''',
'''הצליל פשוט וחם: פסנתר, קול שקט ובוטח, ולהקה קטנה שמלווה בעדינות. I Feel the Earth Move פותח בפסנתר קצבי ומלא שמחה, So Far Away הוא שיר געגועים על אנשים שחיים רחוק, ו־It's Too Late הוא שיר פרידה בוגר, בלי דרמה, על אהבה שפשוט נגמרה. You've Got a Friend הוא הבטחה פשוטה של חברות, שג׳יימס טיילור הקליט באותה תקופה והגיע איתו למקום הראשון. והיא שרה גם גרסאות משלה לשירים שכתבה לאחרים, איטיות ואישיות יותר.''',
'''Tapestry היה אחת ההצלחות הגדולות בתולדות התקליטים: 15 שבועות במקום הראשון באמריקה, ארבעה פרסי גראמי, כולל אלבום השנה, ועשרות מיליוני עותקים. הוא הפך לסמל של גל ה"זמרים־כותבים", ולאלבום שכמעט כל בית בשנות השבעים החזיק. הוא גם הוכיח שאישה שכתבה להיטים מאחורי הקלעים יכולה להיות כוכבת בעצמה.''',
'''שמעו את A Natural Woman בגרסה של קרול קינג, ואז את הגרסה של אריתה פרנקלין באלבום 117: אותו שיר, פעם כהצהרה גדולה של זמרת גוספל, ופעם כלחישה אישית של הכותבת ליד הפסנתר.''',
], [
("It's Too Late", 'שיר פרידה בוגר ושקט, בלי כעס ובלי דרמה. מקום ראשון במצעד.'),
("You've Got a Friend", 'הבטחה פשוטה ומנחמת של חברות, אחד השירים האהובים של העשור.'),
('I Feel the Earth Move', 'הפותח: פסנתר קצבי ושמח, ואהבה שמזיזה את האדמה מתחת לרגליים.'),
])

add(213, [
'''ב־1971 הבמאי והצלם גורדון פארקס ביים את Shaft, סרט על בלש שחור בניו יורק, מהסרטים הראשונים שהציגו גיבור שחור חזק, מגניב ועצמאי. את המוזיקה הוא הזמין מאייזק הייז, שכבר היה כוכב אחרי Hot Buttered Soul (אלבום 165). הייז כתב והקליט פסקול שלם, שיצא כאלבום כפול ונמכר יותר מהסרט עצמו.''',
'''Theme from Shaft, שיר הנושא, הוא אחד הקטעים המזוהים ביותר של שנות השבעים: מצילה שמתופפת במהירות, גיטרה עם וואה־וואה שמקרקרת, כלי מיתר, חצוצרות ומעל כל זה הקול העמוק של הייז, שמדבר יותר משהוא שר ומתאר את הבלש, והמקהלה שעונה לו. אבל האלבום כולל גם קטעים אינסטרומנטליים ארוכים, רובם ג׳אז־פאנק שמלווה את הסצנות בסרט, כמו Soulsville, שיר עצוב על החיים בגטו, ו־Do Your Thing, ג׳אם של כמעט עשרים דקות. הייז עבד עם להקת האולפן של סטקס בממפיס, והנגנים שם, מהטובים בדרום, נתנו לפסקול גרוב חם ומדויק.''',
'''Theme from Shaft הגיע למקום הראשון באמריקה, והייז זכה עליו בפרס האוסקר לשיר המקורי, והיה לאמן השחור הראשון שזכה באוסקר שאינו על משחק. הפסקול הוביל גל שלם של סרטים ופסקולים של "בלאקספלויטיישן", ובהם Superfly של קרטיס מייפילד (אלבום 247), והשפיע רבות על הפאנק, על הדיסקו ועל ההיפ הופ. גם הדימוי של הייז עצמו, עם ראש מגולח, משקפי שמש ושרשראות זהב, הפך לסמל של גאווה שחורה בשנות השבעים.''',
'''שמעו את Theme from Shaft ואחר כך את Soulsville: הראשון מלא ביטחון ומגניבות, השני עצוב וכנה. אם יש לכם זמן, Do Your Thing הוא שיעור בפאנק של כמעט עשרים דקות.''',
], [
('Theme from Shaft', 'מצילה מהירה, גיטרת וואה־וואה והקול העמוק של הייז: שיר שזכה באוסקר.'),
('Soulsville', 'שיר איטי ועצוב על החיים בגטו, עם קולות ליווי רכים.'),
('Do Your Thing', 'ג׳אם פאנק ארוך ומהפנט, שבו כל נגן מקבל מקום משלו.'),
])

add(214, [
'''האחים אולמן, דואן וגרג, הקימו ב־1969 בג׳ורג׳יה להקה עם שני גיטריסטים, שני מתופפים, בס ואורגן, שניגנה בלוז, רוק, ג׳אז וקאנטרי בבת אחת. אלבומי האולפן שלהם לא נמכרו טוב, אבל על הבמה הם היו מדהימים. במרץ 1971 הם הקליטו כמה ערבים באולם Fillmore East בניו יורק, עם המפיק טום דאוד, והתוצאה יצאה ביולי כאלבום כפול. דואן אולמן, שניגן שנה קודם עם אריק קלפטון (אלבום 176), היה אז בשיא.''',
'''השירים ארוכים והנגינה משוחררת: שני הגיטריסטים, דואן אולמן ודיקי בטס, מנגנים יחד מלודיות בהרמוניה, ואחר כך יוצאים לסולואים ארוכים שמשוחחים זה עם זה. Statesboro Blues, השיר הפותח, מציג את הגיטרה של דואן עם מגלשה (סלייד), שנשמעת כמו קול בוכה. In Memory of Elizabeth Reed, קטע אינסטרומנטלי של בטס, הוא מסע ג׳אזי מרגש, ו־Whipping Post, שיר של גרג אולמן, נמתח ליותר מעשרים דקות של עוצמה ורגש.''',
'''At Fillmore East הפך ללהיט, ונחשב לאחד מאלבומי ההופעה הגדולים בתולדות הרוק, אולי הגדול שבהם. אבל שלושה חודשים אחרי שיצא, דואן אולמן נהרג בתאונת אופנוע, בגיל 24. הלהקה המשיכה, והפכה לאבות של "הרוק הדרומי" ושל להקות הג׳אם, שמאלתרות ארוכות על הבמה. שני המתופפים, בוץ׳ טראקס וג׳איימו ג׳והנסון, מנגנים יחד כמו מנוע אחד, והבס של ברי אוקלי מחזיק את כל המבנה.''',
'''שמעו את In Memory of Elizabeth Reed, ותקשיבו איך שני הגיטריסטים מנגנים יחד את המלודיה ואז יוצאים כל אחד לדרכו. אחר כך השוו ל־Key to the Highway (אלבום 176): אותו דואן אולמן, בשיחה עם קלפטון.''',
], [
('Statesboro Blues', 'הפותח: בלוז ישן עם גיטרת סלייד בוכייה של דואן אולמן.'),
('In Memory of Elizabeth Reed', 'קטע אינסטרומנטלי ג׳אזי ומרגש, עם שתי גיטרות שמנגנות בהרמוניה.'),
('Whipping Post', 'יותר מעשרים דקות של בלוז רוק סוער, עם שירה כואבת של גרג אולמן.'),
])

add(215, [
'''ב־1971 הרולינג סטונס עזבו את חברת התקליטים הוותיקה שלהם, הקימו חברה משלהם, ועברו לגור בדרום צרפת כדי להימנע ממסים כבדים בבריטניה. Sticky Fingers היה האלבום הראשון בחברה החדשה, עם הלוגו המפורסם של הלשון והשפתיים, ועם עטיפה שעיצב אנדי וורהול: מכנסי ג׳ינס עם רוכסן אמיתי. זה היה גם האלבום המלא הראשון עם הגיטריסט מיק טיילור, שהחליף את בריאן ג׳ונס.''',
'''חלק מהשירים הוקלטו באולפן Muscle Shoals באלבמה, מקום של סול דרומי, והשפעה של סול, קאנטרי ובלוז נשמעת לאורך כל האלבום. Brown Sugar נפתח בריף בלתי נשכח, אף שהמילים שלו, על עבדות ועל מין, מעוררות מחלוקת עד היום. Wild Horses הוא בלדה קאנטרית רכה ומכאיבה. Can't You Hear Me Knocking מתחיל בריף חד והופך לג׳אם ארוך עם סקסופון וגיטרה בסגנון לטיני, ו־Sister Morphine ו־Moonlight Mile הם שירים אפלים ושקטים על סמים ועל עייפות. הגיטרה של מיק טיילור, מלודית ונקייה, הוסיפה ללהקה צבע חדש, וכמה מהסולואים היפים של הסטונס מגיעים ממנו.''',
'''Sticky Fingers הגיע למקום הראשון באמריקה ובבריטניה, והוא נחשב, יחד עם Beggars Banquet ו־Let It Bleed (אלבומים 107 ו־149), לחלק מהתקופה הגדולה ביותר של הסטונס. הוא גם מראה אותם כלהקה שיודעת להיות גסה וחשופה באותה נשימה.''',
'''שמעו את Wild Horses ואחריו את Can't You Hear Me Knocking: בלדה שקטה ואז ג׳אם של שבע דקות. שימו לב לסיום של השני, כשהסקסופון של בובי קיז והגיטרה של מיק טיילור משתלטים.''',
], [
('Wild Horses', 'בלדה קאנטרית רכה ומכאיבה, מהשירים היפים ביותר של הסטונס.'),
("Can't You Hear Me Knocking", 'ריף חד שהופך לג׳אם ארוך עם סקסופון וגיטרה בסגנון לטיני.'),
('Moonlight Mile', 'שיר הסיום: שקט, עייף ויפהפה, עם כלי מיתר ותחושה של נסיעה בלילה.'),
])

add(216, [
'''שנה אחרי האלבום החשוף והזועם שלו (אלבום 183), ג׳ון לנון הקליט את Imagine באולפן שבנה בביתו הכפרי באנגליה, שוב עם פיל ספקטור כשותף להפקה. הפעם הוא רצה אלבום מלודי ונגיש יותר, או במילים שלו, לעטוף את המסר "בסוכר". ג׳ורג׳ הריסון ניגן בכמה שירים, והאלבום יצא בספטמבר 1971. את רוב השירים הקליט לנון באולפן ביתי, עם חברים ותיקים ונגנים מעולים, באווירה רגועה יחסית לשנה הקודמת.''',
'''שיר הנושא, רק פסנתר, קול וכלי מיתר עדינים, מבקש מהמאזין לדמיין עולם בלי מדינות, בלי דתות ובלי רכוש, והפך לאחד משירי השלום המפורסמים בעולם. Jealous Guy הוא שיר חשוף ויפה על קנאה ועל חרטה, שנולד עוד בימי הביטלס. Gimme Some Truth הוא שיר מחאה חריף נגד שקרים של פוליטיקאים, Oh My Love הוא שיר אהבה שקט ליוקו, ו־How Do You Sleep? הוא התקפה חריפה ואישית על פול מקרטני, שהראתה כמה הפירוד בין השניים היה כואב.''',
'''Imagine הגיע למקום הראשון באמריקה ובבריטניה, והפך לאלבום הסולו המצליח ביותר של לנון. שיר הנושא מושמע בכל העולם בטקסים, באירועים ובזמנים של אבל, ונחשב לאחד השירים המשפיעים של המאה העשרים. האלבום מראה את לנון בשני צדדיו: החולם האופטימי, והאיש הכועס והפגוע. בסרט תיעודי שצולם בזמן ההקלטות אפשר לראות את לנון ויוקו אונו בבית, בגן ובאולפן, ואת העבודה הנינוחה על השירים.''',
'''שמעו את Imagine ואחריו את Mother מאלבום 183: אותו אדם, שנה אחת בהפרש. ואז את Jealous Guy, אולי השיר הכנה ביותר באלבום.''',
], [
('Imagine', 'פסנתר, קול וחלום על עולם בלי גבולות: אחד משירי השלום המפורסמים בעולם.'),
('Jealous Guy', 'שיר חשוף ויפה על קנאה ועל בקשת סליחה, מהכנים שלנון כתב.'),
('Gimme Some Truth', 'שיר מחאה חריף נגד שקרים של פוליטיקאים, עם גיטרה של ג׳ורג׳ הריסון.'),
])

add(217, [
'''בשנות השבעים המוקדמות הביץ׳ בויז נאבקו בתדמית של להקת גלישה מיושנת. בריאן וילסון, הגאון שמאחורי Pet Sounds (אלבום 61), כמעט הפסיק לעבוד, ושאר חברי הלהקה לקחו על עצמם יותר ויותר. מנהל חדש דחף אותם לשירים רציניים יותר, על הסביבה ועל החברה. Surf's Up, שיצא ב־1971, קרוי בכוונה על שם שיר של בריאן מתקופת האלבום האגדי שלא יצא, SMiLE, כאילו לומר שהגלישה נגמרה.''',
'''האחים הצעירים של בריאן נשמעים כאן בוגרים ובטוחים: קרל וילסון כתב ושר את Long Promised Road ו־Feel Flows, שירים חלומיים ומלאי שכבות, עם סינתיסייזר, חליל וגיטרות. Don't Go Near the Water הוא אזהרה על זיהום הים, לא ממש מה שציפו מלהקת גלישה. ובסוף מגיעים שני שירים של בריאן: 'Til I Die, שיר שקט ועצוב על אדם קטן מול ים עצום, ו־Surf's Up, שיר מסובך ויפהפה שנכתב ב־1966 עם המשורר ואן דייק פארקס, ונשמע כמו חלום שבור.''',
'''האלבום החזיר את הביץ׳ בויז לתשומת לב של המבקרים ושל קהל צעיר, והוכיח שהם לא רק להקה של נוסטלגיה. שני השירים האחרונים שלו נחשבים לחלק מהיצירות היפות ביותר של בריאן וילסון, והם נתנו הצצה ראשונה למה שהיה אמור להיות SMiLE. רבים מחשיבים את האלבום לאחד השיאים של הלהקה בשנות השבעים, בזכות השילוב בין הכותבים השונים שבה.''',
'''שמעו את 'Til I Die ו־Surf's Up ברצף, בשקט. אחר כך חזרו ל־God Only Knows באלבום 61, וחשבו על מה שעבר על בריאן וילסון בחמש השנים שבין שני האלבומים.''',
], [
("Surf's Up", 'שיר מסובך ויפהפה של בריאן וילסון מתקופת SMiLE, כמו חלום שבור.'),
("'Til I Die", 'שיר שקט ועצוב על אדם קטן מול ים עצום, בהרמוניות מושלמות.'),
('Feel Flows', 'שיר חלומי ומלא שכבות של קרל וילסון, עם חליל וגיטרות מרחפות.'),
])

add(218, [
'''אחרי ההצלחה של The Yes Album (אלבום 209), יס קיבלו חבר חדש: הקלידן ריק ווייקמן, עם גלימה, שיער ארוך ומגדלים של קלידים, שהביא להקה את היכולת לנגן כמו תזמורת. Fragile יצא בסוף 1971, ועל העטיפה שלו, לראשונה, ציור של האמן רוג׳ר דין, שיצר מאז את העולם החזותי של הלהקה: נופים מרחפים, כוכבים ויצורים מוזרים.''',
'''ארבעה שירים ארוכים של כל הלהקה מתחלפים עם חמישה קטעים קצרים, אחד של כל נגן. Roundabout נפתח בגיטרה אקוסטית ובצליל הפוך, ואז נכנס קו בס מקפץ של כריס סקוויר והשיר הופך למסע מלא אנרגיה. Heart of the Sunrise מתחיל בריף מהיר ומסובך ומגיע לשיא רגשי גדול. בין השירים, סטיב האו מנגן גיטרה קלאסית ב־Mood for a Day, ווייקמן מעבד יצירה של ברהמס לקלידים. הקול הגבוה של ג׳ון אנדרסון מרחף מעל הכול, עם מילים מופשטות על טבע ועל רוחניות. ביל ברופורד, המתופף, מנגן בקצבים מסובכים ומשתנים, וכל שיר נשמע כמו פאזל מוזיקלי שמתחבר בדיוק ברגע הנכון.''',
'''Roundabout הפך ללהיט באמריקה, ו־Fragile פתח ליס את הדלת לקהל האמריקאי. זה אחד האלבומים שהגדירו את הרוק המתקדם, והוא נשמע עד היום כשילוב מפתיע של וירטואוזיות, הרמוניות ומלודיות קליטות. האלבום הבא שלהם, Close to the Edge (אלבום 250), לקח את הרעיונות האלה עוד רחוק יותר.''',
'''התחילו ב־Roundabout וחכו לקו הבס. אחר כך תנו ל־Heart of the Sunrise את כל עשר הדקות שלו: המעבר מהריף המהיר לשירה הרכה הוא אחד הרגעים היפים של יס.''',
], [
('Roundabout', 'גיטרה אקוסטית, קו בס מקפץ ומסע מלא אנרגיה: הלהיט הגדול של יס.'),
('Heart of the Sunrise', 'ריף מהיר ומסובך שמגיע לשיא רגשי גדול, בשיר הסיום.'),
('Mood for a Day', 'קטע גיטרה קלאסית קצר ויפה של סטיב האו, רגע שקט בין הסערות.'),
])

add(219, [
'''ב־1971 הדורס היו מותשים: ג׳ים מוריסון שתה הרבה ועמד למשפט אחרי ההופעה במיאמי, והמפיק הוותיק שלהם, פול רוטשילד, עזב באמצע העבודה ואמר שהשירים החדשים נשמעים לו כמו "מוזיקת קוקטייל". הלהקה החליטה להפיק לבד, עם המהנדס ברוס בוטניק, והקליטה את L.A. Woman בחדר החזרות שלה בלוס אנג׳לס, כמעט כמו בהופעה. האלבום יצא באפריל 1971.''',
'''זה אלבום בלוזי, גולמי ובטוח: הלהקה מנגנת יחד בחדר, וג׳ים מוריסון, בקול עמוק ומחוספס, שר לפעמים מתוך חדר האמבטיה בגלל ההד. שיר הנושא הוא נסיעה בלילה ברחובות לוס אנג׳לס, עם גיטרה דוהרת, והאנגרמה המפורסמת "Mr. Mojo Risin'" שהיא שיכול אותיות של השם של מוריסון. Love Her Madly הוא שיר פופ קליט, ו־Been Down So Long ו־Crawling King Snake הם בלוז כבד. והאלבום נסגר ב־Riders on the Storm, שיר איטי ומאיים עם קולות גשם ורעם ופסנתר חשמלי של ריי מנזרק. הבסיסט האורח ג׳רי שף, שניגן גם עם אלביס פרסלי, נותן לשירים גרוב בלוזי ויציב, שעליו הלהקה יכולה לנוח.''',
'''כמה חודשים אחרי שהאלבום יצא, מוריסון, שעבר לפריז, נמצא מת באמבטיה, בגיל 27. L.A. Woman הוא האלבום האחרון שלו עם הלהקה, ורבים רואים בו את אחד הטובים שלהם, שיבה לשורשי הבלוז ולאנרגיה של ההתחלה. Riders on the Storm היה מהשירים האחרונים שהקליט.''',
'''שמעו את Riders on the Storm בשקט, עם אוזניות, ותנו לגשם לעטוף אתכם. ואחר כך את The End מאלבום הבכורה שלהם (אלבום 93): הראשון והאחרון, ארבע שנים בהפרש.''',
], [
('Riders on the Storm', 'גשם, רעם ופסנתר חשמלי: שיר איטי ומאיים, מהאחרונים שמוריסון הקליט.'),
('L.A. Woman', 'נסיעה לילית דוהרת ברחובות לוס אנג׳לס, עם גיטרה ובס מתגלגלים.'),
('Love Her Madly', 'שיר פופ קליט ושמח, עם פסנתר קופצני, מהלהיטים האחרונים של הלהקה.'),
])

add(220, [
'''Can היו להקה מקלן שבמערב גרמניה, חלק ממה שנקרא אחר כך "קראוטרוק": מוזיקאים גרמנים צעירים שרצו ליצור מוזיקה חדשה, שלא מחקה את הרוק האמריקאי או הבריטי. שניים מהם, הבסיסט הולגר צ׳וקאי והקלידן אירמין שמידט, למדו מוזיקה קלאסית אוונגרדית אצל המלחין קרלהיינץ שטוקהאוזן. הזמר שלהם, דאמו סוזוקי, היה צעיר יפני שהם מצאו מנגן ברחוב במינכן. Tago Mago, אלבום כפול, הוקלט בטירה ישנה ויצא ב־1971.''',
'''הלב של Can הוא המתופף יאקי ליבצייט, שמנגן מקצבים חוזרים, מדויקים ומהפנטים כמו מכונה חיה, ועליהם הלהקה מאלתרת במשך דקות ארוכות. Paperhouse ו־Mushroom הם שירים קצרים ומתוחים, Oh Yeah כולל שירה שהושמעה לאחור, ו־Halleluhwah הוא גרוב של כמעט עשרים דקות, פאנקי ומתגלגל, שנשמע כמו ג׳יימס בראון בחלום. בצד השני, Aumgn ו־Peking O הם ניסויים של רעשים, קולות ואפקטים שנשמעים כמו טקס מוזר. צ׳וקאי ערך את ההקלטות, חתך והדביק אותן לסרט מוזיקלי. הקול של סוזוקי, שר באנגלית, ביפנית ובשפה שהמציא, הוסיף ללהקה חירות ומוזרות שלא היו בה קודם.''',
'''Tago Mago לא היה להיט גדול, אבל ההשפעה שלו עצומה: פאנק, פוסט־פאנק, מוזיקה אלקטרונית, היפ הופ ורוק אלטרנטיבי, מג׳וני ליידן ועד רדיוהד, כולם מדברים על Can. הוא הראה שאפשר לבנות שיר על חזרה ועל גרוב במקום על מלודיה ופזמון.''',
'''התחילו ב־Halleluhwah ותנו לו לרוץ, רצוי בקול רם, בזמן שאתם עושים משהו אחר. אחרי כמה דקות תשימו לב שהגוף שלכם זז לבד. את הצד הניסיוני אפשר לשמור לפעם הבאה.''',
], [
('Halleluhwah', 'גרוב פאנקי מהפנט של כמעט עשרים דקות, על תופים שלא עוצרים.'),
('Paperhouse', 'הפותח: שיר מתוח שמתפרץ ונרגע, עם גיטרה חדה ותופים מדויקים.'),
('Mushroom', 'שיר קצר ומאיים, עם תופים יבשים וקול שחוזר על עצמו.'),
])

add(221, [
'''אלטון ג׳ון, פסנתרן וזמר מפרברי לונדון, והמשורר הצעיר ברני טאופין, שכתב לו את המילים, היו כבר צמד מצליח בתחילת 1971, אחרי השיר Your Song. Madman Across the Water, האלבום הרביעי שלהם, יצא בסוף 1971, עם עיבודים של כלי מיתר של פול בקמאסטר ובהפקת גאס דאדג׳ן, והשירים בו ארוכים, דרמטיים ושאפתניים.''',
'''Tiny Dancer, השיר הפותח, הוא שיר אהבה לאשתו של טאופין, צעירה מלוס אנג׳לס שתפרה את בגדי הלהקה, שמתחיל בפסנתר שקט ונבנה לאט לפזמון גדול. Levon מספר סיפור מוזר ועדין על אב, בן ובלונים, עם כלי מיתר עשירים. שיר הנושא הוא שיר אפל ומתוח, על אדם שאולי יצא מדעתו. ויש גם שירים על ההיסטוריה האמריקאית, כמו Indian Sunset, סיפור קודר מנקודת מבט של אינדיאני. העיבודים של פול בקמאסטר, עם כלי קשת דרמטיים, נותנים לשירים צליל של סרט קולנוע, והפכו לחלק מסימן ההיכר של אלטון בשנים האלה.''',
'''באמריקה האלבום הגיע לעשירייה הראשונה, אבל בבריטניה הוא כמעט לא נמכר. רק עם השנים Tiny Dancer הפך לאחד השירים האהובים של אלטון ג׳ון, במיוחד אחרי סצנה מפורסמת בסרט "כמעט מפורסמים" מ־2000, שבה חברי להקה באוטובוס שרים אותו יחד. האלבום נחשב לאחד השיאים של אלטון ג׳ון לפני שהפך לכוכב־על עם תלבושות ראוותניות. גם הנגנים באלבום היו מהמעולים בלונדון, ובהם הגיטריסט דייבי ג׳ונסטון, שהצטרף אחר כך ללהקה הקבועה של אלטון.''',
'''שמעו את Tiny Dancer עד הסוף, ותנו לפזמון להגיע לאט. אם אתם אוהבים סיפורים, Levon ו־Indian Sunset הם שני סיפורים קצרים בשירים.''',
], [
('Tiny Dancer', 'שיר אהבה שמתחיל בפסנתר שקט ונבנה לפזמון גדול ומרגש.'),
('Levon', 'סיפור מוזר ועדין על אב ובן, עם כלי מיתר עשירים.'),
('Indian Sunset', 'סיפור קודר מנקודת מבט של אינדיאני, עם מקהלה ותזמורת דרמטית.'),
])

add(222, [
'''דולי פרטון גדלה בעוני בבקתה בהרי טנסי, אחת משנים־עשר ילדים, ועברה לנאשוויל יום אחרי שסיימה את התיכון. בסוף שנות השישים היא הופיעה בתוכנית הטלוויזיה של זמר הקאנטרי פורטר וואגונר, ששר איתה דואטים והפיק את התקליטים שלה. Coat of Many Colors, שיצא ב־1971, היה האלבום שבו היא התגלתה ככותבת ענקית, ולא רק כזמרת עם קול צלול ומבטא הררי.''',
'''שיר הנושא מספר סיפור אמיתי מילדותה: אמה תפרה לה מעיל משאריות בד צבעוניות, וסיפרה לה על מעיל הפסים של יוסף בתנ״ך. בבית הספר הילדים צחקו עליה, אבל היא הבינה שהמעיל עשוי מאהבה, ושהיא עשירה יותר מהם. לפי הסיפור, היא כתבה את השיר באוטובוס של הסיבוב, על גב קבלה של מכבסה שהייתה בהישג יד. לצדו יש שירים על אהבה שבורה, כמו My Blue Tears, שירים של פורטר וואגונר, ושיר קטן ויפה על שקט של בוקר, Early Morning Breeze.''',
'''Coat of Many Colors נחשב לאחד מאלבומי הקאנטרי הגדולים, ושיר הנושא הוא השיר שדולי פרטון עצמה אומרת שהיא הכי אוהבת מכל מה שכתבה. הוא מראה את מה שיהפוך לסימן ההיכר שלה: סיפורים פשוטים, מצחיקים ועצובים על חיים של אנשים עניים, בלי רחמים עצמיים. בשנים הבאות היא כתבה את Jolene ואת I Will Always Love You, והפכה לאחת הכוכבות הגדולות באמריקה.''',
'''שמעו את שיר הנושא עם המילים, ואחר כך את Don't Come Home a Drinkin' של לורטה לין (אלבום 102): שתי בנות של הרים עניים, שהפכו את החיים שלהן לשירים ואת עצמן לכוכבות.''',
], [
('Coat of Many Colors', 'שיר הנושא: סיפור אמיתי על מעיל מטלאים שאמא תפרה, ועל עושר של אהבה.'),
('My Blue Tears', 'שיר קצר ועצוב על לב שבור, בקול צלול ובליווי פשוט.'),
('Early Morning Breeze', 'שיר רך ושקט על בוקר בהרים ועל השקט שבטבע.'),
])

add(223, [
'''דון מקלין היה זמר פולק צעיר מניו יורק, שחילק עיתונים כנער. בבוקר אחד של פברואר 1959 הוא קרא בעיתונים שחילק שבאדי הולי (אלבום 8), ריצ׳י ואלנס וביג בופר נהרגו בהתרסקות מטוס. שתים־עשרה שנה אחר כך, ב־1971, הוא הפך את הזיכרון הזה לשיר ארוך בשם American Pie, שנתן את שמו לאלבום השני שלו.''',
'''American Pie נמשך יותר משמונה דקות, ומספר בסמלים ובחידות את סיפור הרוקנרול משנות החמישים ועד סוף שנות השישים: "היום שבו המוזיקה מתה", ליצן, מלך, ג׳יימס דין, ושירה משותפת של פזמון שכולם מכירים. מקלין סירב שנים להסביר את המשמעות, והמאזינים ממשיכים לנחש. השיר השני המפורסם באלבום, Vincent, הוא שיר רך ושקט לצייר וינסנט ואן גוך, על אמן שהעולם לא הבין. ויש גם שירים אישיים ושקטים, כמו Empty Chairs ו־Crossroads. מקלין שר בקול צלול ורך, עם גיטרה אקוסטית ופסנתר, והשירים השקטים משלימים את ה"אפוס" הגדול של שיר הנושא. מקלין כתב את השיר במשך זמן רב, והוא עצמו אמר שהשיר הוא על אמריקה שאיבדה את התמימות שלה, יותר מאשר על אנשים מסוימים.''',
'''American Pie הגיע למקום הראשון באמריקה בתחילת 1972 ונשאר שם ארבעה שבועות, למרות האורך יוצא הדופן. Vincent הגיע למקום הראשון בבריטניה. השיר הפך לאחד השירים האהובים והמצוטטים בתולדות הפופ האמריקאי, שאנשים שרים יחד בחתונות, במסיבות ובערבי שירה. השיר נבחר פעמים רבות לאחד השירים החשובים של המאה העשרים באמריקה, וכתב היד המקורי שלו נמכר במכירה פומבית בסכום עצום. השיר נבחר פעמים רבות לאחד השירים החשובים של המאה העשרים באמריקה, וכתב היד המקורי שלו נמכר במכירה פומבית בסכום עצום.''',
'''שמעו את American Pie ונסו לנחש מי זה מי בסיפור. ואז שמעו את השירים של באדי הולי באלבום 8, כדי לשמוע את "המוזיקה" שמקלין מתגעגע אליה.''',
], [
('American Pie', 'שמונה דקות של היסטוריה של הרוקנרול בסמלים וחידות, עם פזמון שכולם שרים.'),
('Vincent', 'שיר רך ושקט לוינסנט ואן גוך, על אמן שהעולם לא הבין.'),
('Empty Chairs', 'שיר שקט ועצוב על אהבה שהלכה ועל כיסאות ריקים.'),
])

add(224, [
'''Emerson, Lake & Palmer הייתה "סופר־להקה" של שלושה נגנים וירטואוזים: הקלידן קית׳ אמרסון, שהיה ידוע בהופעות פרועות שבהן תקע סכינים בעוגב, הזמר והבסיסט גרג לייק מקינג קרימזון (אלבום 168), והמתופף הצעיר קרל פאלמר. Tarkus, האלבום השני שלהם, יצא באמצע 1971 והגיע למקום הראשון בבריטניה. אמרסון היה גם פסנתרן בעל הכשרה קלאסית, ואהב להכניס לרוק ציטוטים ממלחינים כמו באך, ברטוק ומוסורגסקי.''',
'''צד שלם של התקליט הוא יצירת הנושא: סוויטה של יותר מעשרים דקות בשבעה חלקים, על יצור מוזר, חצי ארמדילו וחצי טנק, שבוקע מביצה ונלחם ביצורים אחרים. המוזיקה מסובכת ומהירה, עם אורגן חשמלי, סינתיסייזר Moog, מקצבים משתנים וקטעים שקטים שבהם לייק שר בקול רך. הצד השני קליל יותר: שירים קצרים, חלקם הומוריסטיים, כמו Jeremy Bender, וחלקם דרמטיים, כמו Bitches Crystal, ויצירה עם מוטיב של באך.''',
'''Tarkus הוא אחד הסמלים של הרוק המתקדם, עם כל מה שאהבו בו ושנאו בו: הווירטואוזיות, השאפתנות, ההשפעה של המוזיקה הקלאסית והאורך. עשור אחר כך, להקות הפאנק ראו ב־ELP דוגמה למה שהן מורדות בו. אבל מוזיקאים רבים, מלהקות מטאל ועד מלחינים של משחקי מחשב, גדלו על הצלילים האלה. ההופעות של הלהקה היו מופעים גדולים, עם מערכות קלידים ענקיות, תופים מסתובבים ובמות מרשימות, והם מילאו אולמות ואצטדיונים.''',
'''שמעו את יצירת הנושא כמו סימפוניה קטנה: שבעה פרקים שכל אחד מהם שונה. אחר כך השוו ל־Pictures at an Exhibition (אלבום 228), שבו אותה שלישייה מנגנת יצירה קלאסית אמיתית.''',
], [
('Tarkus', 'סוויטה של עשרים דקות על יצור חצי ארמדילו וחצי טנק, עם אורגן, Moog ומקצבים משתנים.'),
('Jeremy Bender', 'שיר קצר, מצחיק ומקפץ, בסגנון של פסנתר מערבוני בבר ישן.'),
('Bitches Crystal', 'שיר דרמטי ומהיר עם פסנתר סוער, שירה חזקה ומקצב משתנה.'),
])

add(225, [
'''אחרי שהמבקרים זלזלו באלבום השלישי שלהם (אלבום 187), לד זפלין החליטו להוציא את האלבום הרביעי בלי שם ובלי שם הלהקה על העטיפה, רק ארבעה סמלים מסתוריים, אחד לכל חבר. הם הקליטו אותו בעיקר באחוזה כפרית ישנה באנגליה, Headley Grange, בעזרת אולפן נייד של הרולינג סטונס. האלבום יצא בנובמבר 1971. ארבעת הסמלים הפכו לחלק מהמיתוס של הלהקה, ומעריצים מנסים עד היום לפענח את משמעותם.''',
'''Black Dog נפתח בשירה של פלאנט בלי ליווי, שעונה לה ריף מסובך ומתפתל. Rock and Roll הוא מחווה דוהרת לשנות החמישים, The Battle of Evermore הוא שיר עם בהשראת טולקין, עם מנדולינה וקולה של סנדי דני מפיירפורט קונבנשן (אלבום 170), ו־Going to California הוא שיר אקוסטי ורך. When the Levee Breaks, בלוז ישן על שיטפון, נשען על תופים ענקיים של ג׳ון בונהאם שהוקלטו בחדר המדרגות של האחוזה. ובאמצע כל זה, Stairway to Heaven: שיר שמתחיל בגיטרה אקוסטית ובחליליות, נבנה לאט, ומסתיים בסולו גיטרה ובצעקות.''',
'''האלבום הרביעי הוא אחד האלבומים הנמכרים ביותר בכל הזמנים, עם עשרות מיליוני עותקים. Stairway to Heaven, שמעולם לא יצא כסינגל, הפך לאחד השירים המושמעים ביותר ברדיו האמריקאי של שנות השבעים, ולשיר שכל גיטריסט מתחיל מנסה לנגן. האלבום מאחד את כל מה שלד זפלין היו: בלוז, פולק, רוק כבד ומיסטיקה.''',
'''שמעו את Stairway to Heaven עד הסוף, בלי לדלג. ואז את When the Levee Breaks בקול רם, כדי לשמוע את התופים המפורסמים ביותר ברוק, שהיפ הופ דגם אותם שוב ושוב.''',
], [
('Stairway to Heaven', 'גיטרה אקוסטית וחליליות שנבנים לאט לסולו גדול: אחד השירים המפורסמים ברוק.'),
('Black Dog', 'שירה בלי ליווי וריף מתפתל שעונה לה, בפתיחה בלתי נשכחת.'),
('When the Levee Breaks', 'בלוז ישן על שיטפון, על תופים ענקיים שהוקלטו בחדר מדרגות.'),
])

add(226, [
'''סרז׳ גינסבורג היה הזמר, המשורר והפרובוקטור הגדול של הפופ הצרפתי, עם קול נמוך, סיגריה נצחית ומילים חכמות ומשחקי מילים. ב־1971 הוא הוציא את Histoire de Melody Nelson, אלבום קונספט קצר, פחות מחצי שעה, שמספר סיפור אחד. בת זוגו, השחקנית והזמרת ג׳יין בירקין, מופיעה על העטיפה בתפקיד מלודי. את העיבודים כתב ז׳אן־קלוד ואנייה, והנגנים היו בחלקם נגני אולפן בריטים. גינסבורג כתב באותן שנים שירים לזמרות רבות, והיה כבר מוכר מאוד בצרפת, אבל כאן הוא ניסה לראשונה לספר סיפור שלם באלבום אחד.''',
'''הסיפור מוזר ומטריד: גבר מבוגר נוהג ברולס־רויס, פוגע בנערה צעירה על אופניים, ומתאהב בה, והיא נהרגת בסוף בהתרסקות מטוס. גינסבורג לא שר את הסיפור, אלא כמעט מדקלם אותו, בלחישה, מעל מוזיקה יוצאת דופן: קו בס עמוק ומתגלגל, תופים יבשים, גיטרה חשמלית, ומעל כולם תזמורת מיתרים דרמטית ומקהלה. Melody פותח בבס מהפנט ובגיטרה, Ballade de Melody Nelson הוא שיר קצר ורך, ו־Cargo culte מסיים ביצירה גדולה עם מקהלה, על שבטים באוקיינוס השקט שמחכים למטוסים.''',
'''האלבום לא נמכר הרבה כשיצא, אבל עם השנים הוא הפך לאחד מאלבומי הפופ הצרפתיים המשפיעים ביותר. מוזיקאים כמו בק, להקת Air, Portishead ורבים אחרים דיברו על ההשפעה שלו, והצליל של הבס והמיתרים נדגם שוב ושוב. הנושא שלו, מערכת יחסים בין גבר מבוגר לנערה, נשמע היום מטריד מאוד, וחלק מהקסם שלו הוא גם אי הנוחות שהוא יוצר.''',
'''לא חייבים להבין צרפתית: הקשיבו לבס ולמיתרים ב־Melody, בקול רם. אחר כך את Cargo culte, ושימו לב איך המקהלה והתזמורת בונות סוף כמעט קולנועי.''',
], [
('Melody', 'הפותח: בס מהפנט, גיטרה וקולו הלוחש של גינסבורג, שמתחיל לספר את הסיפור.'),
('Ballade de Melody Nelson', 'שיר קצר ורך על הנערה מלודי, מהרגעים המלודיים ביותר באלבום.'),
('Cargo culte', 'סיום קולנועי עם מקהלה ותזמורת, על שבטים שמחכים למטוסים.'),
])

add(227, [
'''ב־1971 רוד סטיוארט הופיע עם ה־Faces (אלבום 234) והקליט במקביל אלבומי סולו (אלבום 195). Every Picture Tells a Story, אלבום הסולו השלישי שלו, יצא באמצע 1971, עם אותו שילוב של רוק, פולק וסול, וחברי ה־Faces מנגנים בו. חברת התקליטים הוציאה סינגל עם Reason to Believe, ובצד השני שיר בשם Maggie May. תחנות הרדיו העדיפו את הצד השני. סטיוארט הקליט את האלבום במהירות ובאווירה משוחררת, כמעט כמו מסיבה של חברים, וזה נשמע בכל שיר.''',
'''Maggie May מספר על נער צעיר שמתאהב באישה מבוגרת ממנו, ויודע שהוא צריך ללכת. זה שיר אקוסטי, עם גיטרות, תופים שמתגלגלים ומנדולינה שנכנסת בסוף, והקול הצרוד של סטיוארט נשמע כמו חבר שמספר לך סיפור בבר. שיר הנושא הוא רוק קצבי ומשעשע על מסע ברחבי העולם, Mandolin Wind הוא שיר אהבה כפרי ויפהפה, ו־(I Know) I'm Losing You הוא גרסה סוערת לשיר של הטמפטיישנס. יש גם שיר של בוב דילן, Tomorrow Is Such a Long Time.''',
'''Maggie May הגיע למקום הראשון באמריקה ובבריטניה, ובאותו זמן גם האלבום עמד במקום הראשון בשתי המדינות, הישג נדיר. סטיוארט הפך לכוכב בינלאומי, ורבים עדיין רואים באלבום הזה את השיא שלו, לפני שעבר לפופ ולדיסקו בסוף שנות השבעים. המנדוליניסט ריי ג׳קסון מלהקת לינדיספרן מוסיף לשירים צבעים של מוזיקה עממית סקוטית ואירית, שסטיוארט אהב מילדותו.''',
'''שמעו את Maggie May וחכו למנדולינה בסוף. אחר כך את Mandolin Wind, שיר אהבה שקט שנשמע כאילו נכתב בחווה סקוטית.''',
], [
('Maggie May', 'סיפור על נער ואישה מבוגרת, עם גיטרות, תופים מתגלגלים ומנדולינה בסוף. מקום ראשון.'),
('Mandolin Wind', 'שיר אהבה כפרי ויפהפה, עם מנדולינה וקול צרוד ורך.'),
('Every Picture Tells a Story', 'שיר הנושא: רוק קצבי ומשעשע על מסע בעולם ועל אהבה.'),
])

add(228, [
'''ב־1874 כתב המלחין הרוסי מודסט מוסורגסקי יצירה לפסנתר בשם "תמונות בתערוכה", אחרי שביקר בתערוכה של ציורים של חבר שמת: כל פרק מתאר ציור אחר, וביניהם "טיילת" שבה המבקר הולך מתמונה לתמונה. Emerson, Lake & Palmer (אלבום 224) ניגנו גרסה משלהם ליצירה בהופעות, והקליטו אותה בהופעה חיה בניוקאסל שבאנגליה במרץ 1971. האלבום יצא בסוף אותה שנה.''',
'''הם לא מנגנים את היצירה כמו שהיא, אלא הופכים אותה לרוק: אורגן עוצמתי, סינתיסייזר Moog, תופים סוערים, וגם שירים חדשים שכתבו ושזרו בתוכה. Promenade נפתח באורגן של כנסייה, The Gnome הוא קטע מוזר וקופצני, The Sage הוא שיר אקוסטי שקט של גרג לייק עם גיטרה, ו־The Hut of Baba Yaga, על מכשפה מאגדות רוסיות, הוא פרץ של רעש ומהירות. הסיום, The Great Gates of Kiev, הוא המנון גדול ומלכותי. בהדרן הם מנגנים גרסה משעשעת למארש מ"מפצח האגוזים" של צ׳ייקובסקי. בהופעות אמרסון קפץ על העוגב, הפך אותו ותקע בו סכינים, וההקלטה החיה מעבירה משהו מהאנרגיה הפרועה הזאת.''',
'''האלבום הגיע לעשירייה הראשונה בבריטניה, והכיר לקהל רוק צעיר יצירה קלאסית שרבים מהם לא היו שומעים אחרת. הוא מסמל את השאיפה של הרוק המתקדם לחבר בין עולם הקונצרטים לבין הרוק, ונשאר אחד הרגעים המפורסמים של ELP.''',
'''שמעו קודם את היצירה המקורית של מוסורגסקי, לפסנתר או בתזמור של ראוול, ואחר כך את הגרסה הזאת. שימו לב ל־The Great Gates of Kiev: אותה מלודיה, פעם בתזמורת ופעם באורגן ובתופים.''',
], [
('Promenade (Pt. 1)', 'הפתיחה: המלודיה המפורסמת של מוסורגסקי, באורגן עוצמתי של כנסייה.'),
('The Sage', 'שיר אקוסטי שקט ויפה של גרג לייק, עם גיטרה ספרדית.'),
('The Great Gates of Kiev', 'הסיום: המנון גדול ומלכותי, עם אורגן, תופים ושירה של גרג לייק.'),
])

add(229, [
'''לאונרד כהן הקליט את האלבום השלישי שלו בנאשוויל, שוב עם המפיק בוב ג׳ונסטון (אלבום 169), ועם עיבודים של המעבד הבריטי פול בקמאסטר. Songs of Love and Hate יצא ב־1971, וכמו שהשם מבטיח, זה האלבום האפל והאינטנסיבי ביותר שלו: שירים על אהבה, קנאה, בגידה, ייאוש ושנאה עצמית, עם גיטרה אקוסטית, כלי מיתר ומקהלות. כהן היה אז כבר בן שלושים ושש, מבוגר בהרבה מרוב הזמרים של התקופה, וזה נשמע בשירים: יש בהם ניסיון, עייפות ורוך.''',
'''Avalanche פותח בגיטרה מהירה ומתוחה ובקול נמוך ומאיים, מפי דמות פגועה שדורשת אהבה. Dress Rehearsal Rag הוא שיר קשה על אדם שמסתכל במראה ביום רע במיוחד. Famous Blue Raincoat, אולי השיר המפורסם באלבום, בנוי כמכתב שכהן כותב לגבר שהיה מאהב של האישה שלו, מכתב של כעס, סליחה וגעגוע, שחתום "בכנות, ל. כהן". ו־Joan of Arc מסיים בדיאלוג בין ז׳אן ד׳ארק לבין האש ששורפת אותה, עם קול נשי שמלווה את כהן.''',
'''האלבום הגיע לעשירייה הראשונה בבריטניה, ונחשב בעיני רבים לטוב ביותר של כהן בשנות השבעים. Famous Blue Raincoat זכה לגרסאות רבות, והפך לאחד השירים המזוהים איתו. השירים האלה עיצבו את התדמית שלו כזמר של רגשות קשים, אבל גם של יופי, הומור מר וחמלה.''',
'''שמעו את Famous Blue Raincoat כמו שקוראים מכתב: לאט, בשקט, עם המילים. ואז את Bird on the Wire מאלבום 169, כדי לשמוע איך אותו קול יכול גם לבקש סליחה בפשטות.''',
], [
('Famous Blue Raincoat', 'מכתב לגבר שהיה מאהב של אשתו: כעס, סליחה וגעגוע.'),
('Avalanche', 'הפותח: גיטרה מהירה ומתוחה וקול נמוך ומאיים, מפי דמות פגועה.'),
('Joan of Arc', 'דיאלוג בין ז׳אן ד׳ארק לאש, עם קול נשי שמלווה את כהן.'),
])

add(230, [
'''ג׳וני מיצ׳ל, זמרת וכותבת קנדית, כבר הייתה מוכרת בשיריה Both Sides Now ו־Woodstock (אלבום 184), כשב־1970, אחרי פרידה מגראהם נאש, יצאה לטיול ארוך באירופה, כולל תקופה במערות של מטאלה באי כרתים. כשחזרה ללוס אנג׳לס, היא כתבה והקליטה את Blue, שיצא ביוני 1971. לפי הסיפור, כשכריס כריסטופרסון שמע את השירים, הוא אמר לה: "ג׳וני, תשאירי משהו לעצמך".''',
'''זה אחד האלבומים החשופים ביותר שנעשו: השירים מדברים על אהבה, בדידות, חופש, געגועים הביתה ואשמה, בכנות כמעט מכאיבה. היא מנגנת על פסנתר, גיטרה ודולצימר אפלצ׳י, כלי מיתר קטן עם צליל מתוק, ולפעמים מלווים אותה ג׳יימס טיילור (אלבום 201) וסטיבן סטילס. River הוא שיר חורף עצוב שבו היא רוצה להחליק על נהר ולברוח, A Case of You הוא שיר אהבה על מישהו שנמצא לה בדם, Carey הוא שיר שמח מכרתים, ו־Little Green הוא שיר על בת שנולדה לה והיא מסרה לאימוץ, סוד שנחשף לציבור רק יותר מעשרים שנה מאוחר יותר. רוב השירים מוקלטים בפשטות גדולה, כמעט בלי תוספות, כך שנדמה שמיטשל יושבת ממש לידכם ושרה רק לכם.''',
'''Blue נחשב לאחד האלבומים הגדולים בתולדות המוזיקה הפופולרית, ולאבן דרך של כתיבה אישית. זמרות וזמרים רבים, מפרינס ועד טיילור סוויפט, דיברו עליו כהשראה. הקול של מיצ׳ל, שקופץ בין צלילים גבוהים לנמוכים, והאקורדים המיוחדים שהמציאה בגיטרה, הפכו לשפה שלמה.''',
'''שמעו את A Case of You בשקט, ואחר כך את River: אם אתם שומעים את זה בחורף, עוד יותר טוב. זה אלבום לשמוע לבד, ואולי עם מחברת.''',
], [
('A Case of You', 'שיר אהבה על מישהו שנמצא לה בדם, עם דולצימר ושירה עדינה.'),
('River', 'שיר חורף עצוב, עם פסנתר ומלודיה של שיר חג המולד.'),
('Carey', 'שיר שמח וקליל מכרתים, עם דולצימר וגיטרה, על ערבים בבית קפה ליד הים.'),
])

add(231, [
'''ג׳ורג׳ קלינטון ניהל שתי להקות עם אותם נגנים: Parliament, להקת סול ופאנק, ו־Funkadelic, להקה פרועה יותר שחיברה פאנק עם רוק כבד ופסיכדליה, בהשראת ג׳ימי הנדריקס וסליי סטון. Maggot Brain, האלבום השלישי של Funkadelic, יצא ב־1971, עם עטיפה של ראש של אישה צועקת שקבור באדמה. לנגנים של Funkadelic היה חופש כמעט מוחלט באולפן, והם ניגנו לפעמים שעות ארוכות, עד שקלינטון מצא את הרגע הנכון.''',
'''שיר הנושא הוא אחד הקטעים המפורסמים בתולדות הגיטרה החשמלית: יותר מעשר דקות של סולו גיטרה של אדי הייזל, מעל ליווי שקט של גיטרה ותופים. לפי הסיפור, קלינטון אמר להייזל לנגן כאילו הוא הרגע שמע שאמו מתה, ואז לגלות שהיא בחיים. התוצאה היא יבבה ארוכה, כואבת ויפהפייה. אחריו האלבום מתחלף בין סגנונות: Can You Get to That הוא שיר גוספל שמח עם מקהלה, Hit It and Quit It הוא פאנק רוק עם אורגן של ברני וורל, ו־Wars of Armageddon הוא כאוס רעשני ופוליטי.''',
'''Maggot Brain לא היה להיט, אבל הוא אחד האלבומים החשובים של הפאנק האפרו־אמריקאי והאב הקדמון של רוק שחור כבד. הסולו של אדי הייזל נחשב בעיני רבים לאחד הגדולים שנוגנו אי פעם, וגיטריסטים כמו ג׳יי מסקיס וג׳ון פרושיאנטה דיברו עליו. קלינטון המשיך לבנות את האימפריה המוזיקלית שלו, שהשפיעה על פרינס, על ההיפ הופ ועל כל מה שנקרא היום פאנק.''',
'''שמעו את Maggot Brain עם אוזניות, בחושך, מההתחלה עד הסוף. אחר כך את Can You Get to That, כדי לחזור לחיים.''',
], [
('Maggot Brain', 'יותר מעשר דקות של סולו גיטרה כואב ויפהפה של אדי הייזל.'),
('Can You Get to That', 'שיר גוספל שמח עם מקהלה, על מה שמקבלים בחזרה בחיים.'),
('Hit It and Quit It', 'פאנק רוק עם אורגן סוער של ברני וורל ומקהלה של כל הלהקה.'),
])

add(232, [
'''ג׳ניס ג׳ופלין, הזמרת עם הקול הצרוד והסוער מטקסס, התפרסמה עם Big Brother and the Holding Company (אלבום 120), ואחר כך יצאה לדרך עצמאית. ב־1970 היא מצאה סוף סוף להקה שמתאימה לה, Full Tilt Boogie Band, ונכנסה לאולפן בלוס אנג׳לס עם המפיק פול רוטשילד, שעבד עם הדורס. באמצע ההקלטות, באוקטובר 1970, היא נמצאה מתה בחדר המלון שלה ממנת יתר, בגיל 27. Pearl יצא אחרי מותה, בתחילת 1971.''',
'''למרות שלא הספיקה לסיים אותו, זה האלבום המלוטש והבוגר ביותר שלה. Me and Bobby McGee, שיר של כריס כריסטופרסון, הוא סיפור על שני נוודים בדרכים, שג׳ופלין שרה ברוך, בחיוך ובעצב, עד שהוא מתפרץ בסוף. Cry Baby ו־Move Over הם שירי סול ורוק מלאי עוצמה, ו־Mercedes Benz הוא תפילה משעשעת ואירונית שהיא שרה לבד, בלי ליווי, שהוקלטה ימים ספורים לפני מותה. Buried Alive in the Blues נשאר בלי שירה: היא הייתה אמורה להקליט את הקול ביום שבו מתה, והלהקה השאירה אותו אינסטרומנטלי.''',
'''Pearl הגיע למקום הראשון באמריקה ונשאר שם תשעה שבועות, ו־Me and Bobby McGee הגיע גם הוא למקום הראשון, אחרי מותה. היא הפכה לסמל של זמרת שנתנה את כל נשמתה על הבמה, ולחלק מהקבוצה הטרגית של מוזיקאים שמתו בגיל 27, יחד עם ג׳ימי הנדריקס וג׳ים מוריסון.''',
'''שמעו את Me and Bobby McGee ואז את Mercedes Benz: שני צדדים של אותה זמרת, הרגשית והמצחיקה. ואחר כך את Ball and Chain מאלבום 120, כדי לשמוע מאיפה היא התחילה.''',
], [
('Me and Bobby McGee', 'סיפור על שני נוודים בדרכים, בשירה רכה שמתפרצת בסוף. מקום ראשון אחרי מותה.'),
('Cry Baby', 'שיר סול סוער, שבו ג׳ופלין צועקת ומתחננת בכל הכוח.'),
('Mercedes Benz', 'תפילה משעשעת ואירונית בלי ליווי, מההקלטות האחרונות של ג׳ופלין.'),
])

add(233, [
'''פלה קוטי, מוזיקאי מלאגוס שבניגריה, למד מוזיקה בלונדון, וב־1969 בילה תקופה בארצות הברית, שם נחשף לג׳יימס בראון ולתנועת זכויות השחורים. כשחזר לניגריה הוא יצר סגנון חדש, אפרוביט: שילוב של היילייף מערב־אפריקאי, פאנק, ג׳אז ומקצבים של שבט היורובה, בשירים ארוכים עם כלי נשיפה ושירה של קריאה ומענה. ג׳ינג׳ר בייקר, המתופף של קרים (אלבום 88), עבר באותה תקופה לגור בניגריה והתיידד איתו. ביולי 1971 הם הקליטו יחד את האלבום הזה באולפן של EMI בלונדון, בהופעה חיה מול קהל קטן שהוזמן לאולפן.''',
'''ארבעה קטעים ארוכים בנויים על גרוב שלא עוצר: גיטרות קצביות שחוזרות על אותו מוטיב, בס עמוק, כלי נשיפה חדים, והתופים של טוני אלן, המתופף המבריק של פלה, שבייקר מצטרף אליו בחלק מהקטעים. פלה מנגן באורגן חשמלי ושר, ביורובה ובאנגלית פשוטה, עם מקהלה שעונה לו. Let's Start פותח בקצב מהיר ושמח, Black Man's Cry הוא שיר על גאווה שחורה, ו־Ye Ye De Smell הוא גרוב איטי ומתגלגל.''',
'''זה אחד האלבומים הראשונים שהכירו את האפרוביט לקהל מחוץ לאפריקה. בשנים הבאות פלה הפך לאחד המוזיקאים הפוליטיים והנועזים בעולם, שיצא בשיריו נגד השלטון הצבאי בניגריה ושילם על כך מחיר כבד. טוני אלן נחשב לאחד המתופפים הגדולים בעולם, והאפרוביט השפיע על מוזיקאים רבים, מבריאן אינו ודייוויד ביירן ועד מוזיקאים אפריקאים ואמריקאים של היום.''',
'''זו מוזיקה לריקוד, לא להאזנה בישיבה. שמעו את Let's Start בקול רם, והקשיבו לתופים של טוני אלן: מקצב שכמעט לא חוזר על עצמו, ובכל זאת לא עוצר לרגע.''',
], [
("Let's Start", 'הפותח: גרוב מהיר ושמח עם כלי נשיפה חדים ותופים של גינגר בייקר.'),
("Black Man's Cry", 'שיר על גאווה שחורה, עם שירה של קריאה ומענה.'),
('Ye Ye De Smell', 'גרוב איטי ומתגלגל, עם אורגן, גיטרות וכלי נשיפה שמשוחחים.'),
])

add(234, [
'''ה־Faces נולדו מהסמול פייסס (אלבום 126), אחרי שהזמר שלהם עזב, כשרוד סטיוארט והגיטריסט רון ווד הצטרפו לשלושת הנותרים. בזמן שסטיוארט הפך לכוכב סולו (אלבום 227), הלהקה נשארה כנופיה של חברים שאהבו לשתות, לצחוק ולנגן רוקנרול מחוספס. A Nod Is as Good as a Wink… to a Blind Horse, האלבום השלישי שלהם, יצא בסוף 1971, בהפקת גלין ג׳ונס.''',
'''זה אלבום של פאב: רוקנרול, בלוז ובלדות, מנוגנים כאילו כולם עומדים יחד על במה קטנה. Stay with Me הוא הלהיט, רוק בועט ומהיר עם גיטרת סלייד של רון ווד וקול צרוד של סטיוארט, על לילה אחד ולא יותר. Debris, שכתב ושר הבסיסט רוני ליין, הוא שיר רך ומרגש על אב, על זבל ועל זיכרונות. Miss Judy's Farm הוא רוק כבד וקצבי, ו־Memphis הוא גרסה לשיר של צ׳אק ברי. יש גם שירים מצחיקים וחצופים, כמו You're So Rude. איאן מקלגן בקלידים וקני ג׳ונס בתופים נותנים ללהקה גרוב חם של רוקנרול ישן, והכול נשמע כמו חברים שנהנים יחד.''',
'''האלבום הגיע למקום השני בבריטניה, ו־Stay with Me הפך לאחד השירים המזוהים עם הלהקה. ה־Faces לא החזיקו מעמד הרבה אחר כך: סטיוארט היה עסוק מדי, ורון ווד הצטרף לרולינג סטונס. אבל הם נשארו השראה ללהקות שרוצות לנגן רוקנרול בשמחה ובלי יומרות, מהריפלייסמנטס ועד הבלאק קראוז.''',
'''שמעו את Stay with Me בקול רם, ואחר כך את Debris: הלהקה הכי פרועה בפאב, והשיר הכי עדין באלבום.''',
], [
('Stay with Me', 'רוק בועט עם גיטרת סלייד וקול צרוד: הלהיט של הלהקה.'),
('Debris', 'שיר רך ומרגש של רוני ליין, על אב, זבל וזיכרונות.'),
("Miss Judy's Farm", 'הפותח: רוק כבד וקצבי עם ריף גיטרה מתגלגל וקול צרוד.'),
])

add(235, [
'''פלמין גרוביז הגיעו מסן פרנסיסקו, אבל בזמן ששאר להקות העיר ניגנו אלתורים פסיכדליים ארוכים, הם אהבו רוקנרול קצר, מהיר ומחוספס של שנות החמישים, כמו של צ׳אק ברי ושל הרולינג סטונס המוקדמים. הם נראו ונשמעו לא מתאימים לזמן ולמקום. Teenage Head, האלבום השלישי שלהם, יצא ב־1971.''',
'''שני גיטריסטים, רוי לוני וסיריל ג׳ורדן, מנגנים גיטרות חשמליות חשופות ובועטות, בלי אפקטים ובלי סולואים ארוכים. שיר הנושא הוא רוק מאיים ומגושם על נער מתבגר, High Flyin' Baby הוא בלוז מלוכלך, ו־Have You Seen My Baby? הוא שיר של רנדי ניומן (אלבום 241) בגרסה מהירה ושמחה. יש גם גרסה לשיר של בלוז ישן של רוברט ג׳ונסון, 32-20, ו־City Lights, שיר איטי ועצוב. הכול נשמע כאילו הוקלט בחדר חזרות קטן.''',
'''האלבום כמעט לא נמכר, ולפי סיפור שמספרים עד היום, מיק ג׳אגר אמר שהוא טוב יותר מ־Sticky Fingers (אלבום 215) שיצא באותו זמן. עם השנים הוא נחשב לאחד האלבומים שהכינו את הקרקע לפאנק: רוקנרול פשוט, מהיר וחזק, בזמן שכולם ניגנו ארוך ומסובך. הלהקה המשיכה, ובאמצע שנות השבעים הפכה לחביבה על להקות פאנק ופאוור פופ. המפיק ריצ׳רד רובינסון נתן להם צליל חשוף ויבש, שהיה אז כמעט לא אופנתי, ודווקא בגלל זה נשמע היום רענן כל כך.''',
'''שמעו את שיר הנושא ואחריו את Brown Sugar מאלבום 215: שני שירי רוקנרול מאותה שנה, אחד מלהקה ענקית ואחד מלהקה שאף אחד לא הכיר.''',
], [
('Teenage Head', 'שיר הנושא: רוק מאיים ומגושם על נער מתבגר, עם גיטרות חשופות.'),
("High Flyin' Baby", 'הפותח: בלוז רוק מלוכלך ובועט, עם שתי גיטרות רועשות.'),
('City Lights', 'שיר איטי ועצוב על אורות העיר, הרגע השקט באלבום.'),
])

add(236, [
'''ג׳ין קלארק היה הכותב העיקרי של הבירדס בתחילת דרכם (אלבומים 57 ו־63), אבל ב־1966 עזב את הלהקה, בין השאר בגלל פחד טיסה. הקריירה שלו כסולן נעה בין אלבומים מוערכים להצלחה מסחרית צנועה. האלבום שנקרא בשמו, ושמכונה לפעמים White Light על שם שיר מתוכו, יצא ב־1971, בהפקת הגיטריסט ג׳סי אד דייוויס.''',
'''זה אלבום שקט, אקוסטי ומהורהר: גיטרות אקוסטיות, מפוחית, קצת פסנתר וגיטרת סלייד עדינה, וקולו העמוק והעצוב של קלארק. The Virgin פותח בסיפור על נערה שמתבגרת בעולם קשה, White Light הוא שיר מסתורי ורוחני, ו־For a Spanish Guitar הוא שיר ארוך ויפהפה על אמן ועל כלי הנגינה שלו, שלפי הסיפור בוב דילן אמר שהיה רוצה לכתוב בעצמו. יש גם גרסה ל־Tears of Rage, שיר שכתבו דילן וריצ׳רד מנואל מ־The Band (אלבום 127). הקול של קלארק נשמע כאן חשוף במיוחד, וכל שיר נשמע כמו וידוי שקט של אדם שחי הרבה והרגיש הרבה.''',
'''האלבום לא נמכר טוב באמריקה, אף שבהולנד דווקא אהבו אותו מאוד. עם השנים קלארק התגלה מחדש כאחד הכותבים העמוקים והמוערכים של הקאנטרי־רוק והפולק האמריקאי, והאלבום הזה נחשב לאחד השיאים שלו. בשנים האחרונות האלבום יצא מחדש, והביקורות עליו היו נלהבות, כאילו התגלה עכשיו לראשונה.''',
'''שמעו את For a Spanish Guitar בשקט, עם המילים. ואחר כך את I'll Feel a Whole Lot Better מאלבום 57, השיר שקלארק כתב לבירדס: אותו אדם, שש שנים אחר כך, בוגר ועצוב יותר.''',
], [
('For a Spanish Guitar', 'שיר ארוך ויפהפה על אמן וכלי הנגינה שלו, מהשירים הטובים של קלארק.'),
('White Light', 'שיר מסתורי ורוחני, עם גיטרה אקוסטית ומפוחית שנותנים לו אור.'),
('The Virgin', 'הפותח: סיפור על נערה שמתבגרת בעולם קשה, עם מלודיה חמה.'),
])

add(237, [
'''ג׳ון פריין היה דוור בפרברי שיקגו, שחיבר שירים בראש בזמן שחילק מכתבים. הוא התחיל לשיר במועדוני פולק בעיר, והזמר כריס כריסטופרסון שמע אותו והתלהב. אלבום הבכורה שלו הוקלט בממפיס, באותו אולפן American Sound שבו הקליט אלביס את From Elvis in Memphis (אלבום 152), עם חלק מאותם נגנים. הוא יצא ב־1971.''',
'''פריין כותב על אנשים רגילים בכנות, בהומור ובחמלה נדירה, בקול פשוט ומחוספס ועם גיטרה אקוסטית. Sam Stone הוא סיפור קורע לב על חייל ששב מווייטנאם, מכור למורפיום, מנקודת המבט של ילדיו. Hello in There הוא שיר על זוג קשישים שנשכח על ידי העולם, Angel from Montgomery מסופר מפי אישה בגיל העמידה שחולמת לברוח, ו־Paradise הוא שיר על עיירת כורים בקנטקי שנהרסה בגלל כרייה. ויש גם שירים מצחיקים, כמו Illegal Smile ו־Spanish Pipedream.''',
'''האלבום לא הפך ללהיט, אבל זמרים רבים הקליטו את השירים שלו, ובוני רייט הפכה את Angel from Montgomery לאחד השירים המזוהים איתה. פריין נחשב לאחד הכותבים הגדולים בתולדות הפולק והקאנטרי האמריקאי, ודילן, ג׳וני קאש ורבים אחרים דיברו עליו בהערצה. הוא המשיך לכתוב ולהופיע עד מותו ב־2020. בכל שיר שלו יש משהו פשוט ומפתיע: משפט אחד שנשמע כמו שיחה בבית קפה, ופתאום מתגלה בו עולם שלם.''',
'''שמעו את Hello in There ו־Sam Stone עם המילים. אחר כך נסו את Angel from Montgomery, ושימו לב איך גבר צעיר בן 24 הצליח לכתוב בקול של אישה מבוגרת ועייפה.''',
], [
('Sam Stone', 'סיפור קורע לב על חייל מכור ששב מווייטנאם, מנקודת המבט של ילדיו.'),
('Hello in There', 'שיר על זוג קשישים שהעולם שכח, עדין, מרגש וחכם.'),
('Angel from Montgomery', 'אישה עייפה שחולמת לברוח: אחד השירים המפורסמים של פריין.'),
])

add(238, [
'''הארי נילסון היה זמר עם קול יוצא דופן, רחב ומתוק, וכותב מוכשר, שהביטלס כינו אותו פעם הזמר האמריקאי האהוב עליהם. בסוף שנות השישים הוא נודע בעיקר בזכות Everybody's Talkin' מהסרט "קאובוי של חצות", שיר של פרד ניל (אלבום 62). ב־1971 הוא נסע ללונדון עם המפיק ריצ׳רד פרי, והקליט את Nilsson Schmilsson, האלבום הכי מצליח שלו. נילסון היה ידוע גם בזכות קול בעל טווח רחב במיוחד, והוא נהג להקליט את עצמו בשכבות רבות, כמו מקהלה של אדם אחד.''',
'''הלהיט הגדול הוא Without You, שיר של להקת Badfinger, שנילסון שר בקול שנבנה משקט עצוב לצעקה עצומה, עם כלי מיתר. אבל שאר האלבום מגוון ומשעשע: Coconut הוא שיר מצחיק שבנוי כולו על אקורד אחד, ובו שלוש דמויות מדברות, Jump into the Fire הוא רוק כבד ואפל עם בס מתפתל ותופים, ו־Gotta Get Up פותח בשיר עליז על השכמה ועל חיים שעוברים מהר. יש גם שירי אהבה שקטים, כמו The Moonbeam Song.''',
'''Without You הגיע למקום הראשון באמריקה ובבריטניה, והאלבום הפך את נילסון לכוכב. בשנים הבאות הוא התפרסם יותר בגלל המסיבות עם ג׳ון לנון בלוס אנג׳לס מאשר בגלל המוזיקה, והקול שלו נפגע. אבל Nilsson Schmilsson נשאר עדות לכישרון נדיר, שנע בין דרמה, הומור ורוק. ריצ׳רד פרי, המפיק, עזר לו לאסוף נגנים מעולים בלונדון, והצליל של האלבום מלוטש, חם ובטוח.''',
'''שמעו את Without You עד הצעקה הגדולה, ואז את Coconut, כדי לצחוק. ההבדל ביניהם הוא כל נילסון.''',
], [
('Without You', 'בלדה שנבנית משקט עצוב לצעקה עצומה, עם כלי מיתר. מקום ראשון.'),
('Coconut', 'שיר מצחיק על אקורד אחד, שבו שלוש דמויות מדברות.'),
('Jump into the Fire', 'רוק כבד ואפל עם בס מתפתל ותופים סוערים, וצעקות של נילסון.'),
])

add(239, [
'''מארק בולאן התחיל בסוף שנות השישים כחצי מצמד פולק פסיכדלי בשם Tyrannosaurus Rex, עם גיטרה אקוסטית, תופי בונגו ושירים על פיות וקוסמים. ב־1970 הוא קיצר את השם ל־T. Rex, חיבר גיטרה חשמלית, והתחיל לכתוב שירי רוקנרול קצרים וסקסיים. Electric Warrior, שיצא בספטמבר 1971, בהפקת טוני ויסקונטי, הפך אותו לאליל נוער בבריטניה ולאחד היוצרים של הגלאם רוק.''',
'''הצליל פשוט, חושני ושובב: ריפים של גיטרה, מחיאות כפיים, כלי מיתר, והקול הרועד והלוחש של בולאן, עם הרמוניות מוגזמות. Get It On הוא הלהיט הגדול, רוקנרול איטי ומגרה עם פסנתר וסקסופון. Jeepster הוא בלוז קופצני על אהבה ומכוניות, Mambo Sun פותח בגרוב רך ומהפנט, ו־Cosmic Dancer הוא שיר עצוב ויפהפה, עם כלי מיתר, על אדם שרוקד מלידתו ועד מותו. בזמן ההקלטות בולאן ניגן בגיטרה חשמלית פשוטה, עם צליל חם ורך, והמתופף ביל לג׳נד, הבסיסט סטיב קארי ונגן ההקשה מיקי פין מחזיקים קצב מתנדנד.''',
'''Get It On הגיע למקום הראשון בבריטניה ולעשירייה הראשונה באמריקה, והאלבום עמד בראש המצעד הבריטי שבועות ארוכים. באותה תקופה דיברו בבריטניה על "T. Rextasy", שיגעון הטי רקס. בולאן, עם נצנצים על הלחיים ומעילים צבעוניים, השפיע על דייוויד בואי (אלבום 240), על סלייד (אלבום 248) ועל כל גל הגלאם. הוא נהרג בתאונת דרכים ב־1977, בגיל 29.''',
'''שמעו את Get It On ואחריו את Cosmic Dancer: הצד המגרה והצד העצוב של בולאן. ואחר כך את Hunky Dory של בואי (אלבום 240), שיצא כמה חודשים אחר כך.''',
], [
('Get It On', 'רוקנרול איטי ומגרה עם פסנתר וסקסופון, הלהיט הגדול של T. Rex.'),
('Cosmic Dancer', 'שיר עצוב ויפהפה עם כלי מיתר, על ריקוד מהלידה ועד המוות.'),
('Jeepster', 'בלוז קופצני ושובב על אהבה ומכוניות, עם מחיאות כפיים.'),
])

add(240, [
'''דייוויד בואי כבר התפרסם ב־1969 עם Space Oddity, אבל האלבומים הבאים שלו לא הצליחו. ב־1971, כשהוא אב טרי ומלא רעיונות, הוא כתב שירים על פסנתר, והקליט אותם עם הגיטריסט מיק רונסון ועם הקלידן ריק ווייקמן, שהצטרף מאוחר יותר ליס (אלבום 218). Hunky Dory יצא בסוף 1971.''',
'''זה אלבום של שירי פופ מבריקים ומגוונים, שבו בואי מתנסה בסגנונות ובזהויות. Changes הוא שיר על שינוי ועל נעורים, עם פסנתר קופצני וסקסופון, Life on Mars? הוא בלדה דרמטית עם פסנתר וכלי מיתר, על נערה שבורחת לקולנוע מחייה העגומים, ו־Kooks הוא שיר מתוק לבנו התינוק. יש שירי מחווה לאנדי וורהול, לבוב דילן ולוולווט אנדרגראונד: Queen Bitch נשמע כמעט כמו שיר של לו ריד (אלבום 153). Oh! You Pretty Things ו־Quicksand עוסקים בעתיד, באלים ובמשבר זהות. רונסון עיבד חלק מכלי הקשת, ובכך התחיל את השותפות שתוביל שנה אחר כך לזיגי סטארדאסט (אלבום 267).''',
'''Hunky Dory לא נמכר טוב בהתחלה, אבל אחרי שבואי הפך לזיגי סטארדאסט ב־1972, גם הוא עלה במצעדים. היום הוא נחשב לאחד האלבומים הגדולים של בואי, והשירים Changes ו־Life on Mars? הם מהמוכרים ביותר שלו. שנה אחר כך בואי הפיק את Transformer של לו ריד (אלבום 251), וכך נסגר מעגל. רבים רואים בו את האלבום שבו בואי מצא את קולו ככותב, לפני שהפך לדמויות ולתחפושות.''',
'''שמעו את Life on Mars? בשקט, ותקשיבו לפסנתר של ריק ווייקמן. ואז את Queen Bitch, ונסו לדמיין את לו ריד שר אותו.''',
], [
('Life on Mars?', 'בלדה דרמטית עם פסנתר וכלי מיתר, מהשירים הגדולים של בואי.'),
('Changes', 'הפותח: שיר על שינוי ונעורים, עם פסנתר קופצני וגמגום מפורסם בפזמון.'),
('Queen Bitch', 'רוקנרול חצוף במחווה ללו ריד ולוולווט אנדרגראונד, עם גיטרה של רונסון.'),
])

add(241, [
'''רנדי ניומן גדל במשפחה של מלחיני פסקולים בהוליווד, וכתב שירים לזמרים אחרים לפני שהתחיל לשיר בעצמו, בקול עייף ומשונה ובפסנתר. הוא כותב שירים מפי דמויות, לעתים קרובות אנשים לא נחמדים, בהומור עוקצני ובאירוניה שלא כולם מבינים. Sail Away, האלבום הרביעי שלו, יצא ב־1972, עם תזמורת שהוא ניצח עליה בעצמו.''',
'''שיר הנושא הוא שיר יפהפה ומרגש, עם מלודיה חמה וכלי מיתר, אבל מי ששר אותו הוא סוחר עבדים, שמנסה לשכנע אפריקאים לעלות לספינה ולבוא לאמריקה, "שבה כולם שמחים". Political Science הוא שיר עליז מפי אמריקאי שמציע להטיל פצצת אטום על כל העולם, כי "אף אחד לא אוהב אותנו". God's Song מסופר מפי אלוהים שצוחק על האנושות. אבל יש גם שירים עדינים ורכים, כמו Dayton, Ohio – 1903 ו־Lonely at the Top, ו־You Can Leave Your Hat On, שיר מפתה שג׳ו קוקר הפך לשיר מפורסם. התזמורת של ניומן מלאה בכלי קשת ונשיפה עדינים, כמו בסרטים הוליוודיים ישנים, ודווקא היופי שלה הופך את המילים הקשות לחזקות עוד יותר.''',
'''Sail Away נחשב לאחד האלבומים הטובים והחכמים של ניומן, ולאחד הדוגמאות היפות לשירים שמשתמשים באירוניה כדי לדבר על גזענות, מלחמה ודת. מאוחר יותר ניומן התפרסם בקהל רחב כמלחין פסקולים לסרטים, ובהם "צעצוע של סיפור", אבל השירים שלו משנות השבעים הם השיא שלו ככותב.''',
'''שמעו את Sail Away פעמיים: פעם בלי המילים, ותהנו מהמלודיה, ופעם עם המילים, ותרגישו את הצמרמורת. זה כל הקסם של רנדי ניומן.''',
], [
('Sail Away', 'מלודיה חמה ויפהפה מפי סוחר עבדים: שיר מרגש ומטלטל.'),
('Political Science', 'שיר עליז ומבהיל מפי אמריקאי שמציע להטיל פצצת אטום על כל העולם.'),
('You Can Leave Your Hat On', 'שיר מפתה ומשעשע על גבר שמבקש מאישה להשאיר את הכובע, שג׳ו קוקר הפך לשיר מפורסם.'),
])

add(242, [
'''בדצמבר 1971 דיפ פרפל (אלבום 188) נסעו למונטרו שבשווייץ, כדי להקליט אלבום חדש באולם הקזינו של העיר, עם אולפן נייד של הרולינג סטונס. בערב שלפני תחילת העבודה, בהופעה של פרנק זאפה (אלבום 174) באותו קזינו, מישהו מהקהל ירה זיקוק, והבניין עלה באש ונשרף עד היסוד. הלהקה צפתה בעשן שנפרש מעל אגם ז׳נבה, ואחרי כמה ימים של חיפושים הקליטה את האלבום במסדרונות של מלון ריק. Machine Head יצא במרץ 1972.''',
'''מתוך השריפה נולד Smoke on the Water, שמספר את כל הסיפור הזה, עם ריף של ארבעה צלילים שהוא אולי המפורסם ביותר בתולדות הגיטרה החשמלית. אבל זה רק שיר אחד: Highway Star פותח את האלבום בשיר מהיר על מכונית ועל מהירות, עם סולו אורגן של ג׳ון לורד וסולו גיטרה של ריצ׳י בלקמור שנשמעים כמו יצירות באך. Lazy הוא בלוז שמח עם אורגן מעוות, ו־Space Truckin' סוגר ברוק כבד ומשעשע על משאיות בחלל.''',
'''Machine Head הגיע למקום הראשון בבריטניה, נמכר במיליונים והפך לאחד מאלבומי ההארד רוק החשובים. Smoke on the Water הפך לשיר הראשון שגיטריסטים מתחילים לומדים, ולפי בדיחה נפוצה, בחנויות גיטרות אוסרים לנגן אותו, כי כל מי שנכנס מנגן בדיוק אותו דבר. דיפ פרפל נסעו אחרי זה ליפן והקליטו את Made in Japan (אלבום 249).''',
'''שמעו את Smoke on the Water ותקשיבו למילים: זו כתבה עיתונאית קטנה על לילה אחד בשווייץ. אחר כך את Highway Star בקול רם, רצוי לא בזמן נהיגה.''',
], [
('Smoke on the Water', 'הריף המפורסם, וסיפור אמיתי על קזינו שנשרף במונטרו בזמן הופעה.'),
('Highway Star', 'הפותח: שיר מהיר על מהירות, עם סולואים של אורגן וגיטרה בהשראת באך.'),
('Lazy', 'בלוז שמח ומשוחרר עם אורגן מעוות, מפוחית וגיטרה מהירה.'),
])

add(243, [
'''אלכס צ׳ילטון היה בן 16 כששר את The Letter עם להקת Box Tops והגיע למקום הראשון באמריקה. כמה שנים אחר כך, בממפיס, הוא הצטרף לכריס בל, כותב ומוזיקאי מקומי, ולשני חברים, והם הקימו את Big Star. השם נלקח משלט של רשת סופרמרקטים, והשם של האלבום הראשון שלהם, #1 Record, היה בדיחה אופטימית. הוא יצא ב־1972 בחברה קטנה, Ardent, שחולקה על ידי Stax.''',
'''Big Star ניגנו מה שנקרא מאוחר יותר "פאוור פופ": שירי רוק קצרים, קליטים ומלאי רגש, עם גיטרות מצלצלות והרמוניות בהשראת הביטלס והבירדס, אבל עם עצב וכנות של נעורים. The Ballad of El Goodo הוא שיר עם הרמוניות יפהפיות על עמידה בלחץ, In the Street הוא רוק קצבי ושמח על נערים שמסתובבים ברחוב, ו־Thirteen הוא שיר אקוסטי מתוק ועדין על אהבה ראשונה בגיל 13. יש גם שירים אפלים ושקטים יותר, כמו Watch the Sunrise ו־Give Me Another Chance.''',
'''המבקרים אהבו את האלבום מאוד, אבל Stax התקשתה להפיץ אותו, וכמעט אף אחד לא הצליח לקנות אותו בחנויות. כריס בל עזב את הלהקה, ונהרג בתאונת דרכים ב־1978. עם השנים Big Star התגלו מחדש, והשפיעו על להקות כמו R.E.M., הריפלייסמנטס, שאפילו כתבו שיר בשם Alex Chilton, וטינייג׳ פאנקלאב. In the Street הפך לשיר הנושא של הסדרה "מופע שנות ה־70".''',
'''שמעו את Thirteen ותיזכרו באהבה הראשונה שלכם. ואז את The Ballad of El Goodo, והקשיבו להרמוניות: להקה קטנה מממפיס שנשמעת כמו הביטלס.''',
], [
('Thirteen', 'שיר אקוסטי מתוק ועדין על אהבה ראשונה בגיל 13.'),
('The Ballad of El Goodo', 'שיר עם הרמוניות יפהפיות על עמידה בלחץ, אחד השירים האהובים של הלהקה.'),
('In the Street', 'רוק קצבי ושמח על נערים ברחוב, שהפך לשיר נושא של סדרה.'),
])

add(244, [
'''אחרי שלושה אלבומים שהוקלטו מהר ובזול באנגליה (אלבומים 179 ו־185), בלאק סבאת׳ קיבלו ב־1972 תקציב גדול, ונסעו להקליט בלוס אנג׳לס. הם שכרו אחוזה בבל אייר, ושקעו במסיבות ובסמים, בעיקר קוקאין. במקור הם רצו לקרוא לאלבום Snowblind, על שם אחד השירים, אבל חברת התקליטים סירבה, והשם הפך ל־Vol 4. האלבום יצא בספטמבר 1972, וטוני איומי הפיק אותו בעצמו.''',
'''הצליל כבד ואיטי כמו תמיד, אבל מגוון ושאפתני יותר. Wheels of Confusion פותח ביצירה של שמונה דקות, עם חלקים משתנים וסולו גיטרה ארוך. Supernaut הוא ריף מהיר ומתפוצץ, אולי אחד הטובים של איומי, ו־Snowblind הוא שיר כבד ואיטי על קוקאין. אבל יש גם הפתעות: Changes הוא בלדה עצובה על פרידה, רק פסנתר, מלוטרון והקול השבור של אוזי אוסבורן, ו־Laguna Sunrise הוא קטע אקוסטי שקט עם גיטרה וכלי מיתר. גיזר באטלר, הבסיסט, כתב את רוב המילים, והן עוסקות גם הפעם בעולם, במלחמה ובפחד, אבל יש בהן יותר ספק ועייפות.''',
'''Vol 4 הראה שבלאק סבאת׳ יכולים להיות יותר מהריפים הכבדים, והשפיע מאוד על להקות מטאל, סטונר רוק וגראנג׳. להקות כמו נירוונה, סאונדגרדן ומטאליקה דיברו עליו כהשראה, ו־Changes זכה לגרסאות מפתיעות, כולל דואט של אוזי עם בתו קלי שהגיע למקום הראשון בבריטניה ב־2003. האלבום נשמע כמו להקה שמרגישה לראשונה חופשייה לנסות דברים חדשים, בלי לחץ של זמן ושל כסף.''',
'''שמעו את Supernaut בקול רם ואחריו את Changes: הלהקה הכי כבדה בעולם, עם פסנתר ולב שבור. תופתעו כמה זה עובד.''',
], [
('Supernaut', 'ריף מהיר ומתפוצץ, מהטובים של טוני איומי, עם תופים דוהרים.'),
('Changes', 'בלדה עצובה על פרידה, עם פסנתר, מלוטרון והקול השבור של אוזי.'),
('Snowblind', 'שיר כבד ואיטי עם ריף עצום, שנתן לאלבום את שמו המקורי.'),
])

add(245, [
'''וולטר בקר ודונלד פייגן נפגשו בקולג׳ בניו יורק בסוף שנות השישים, ושניהם אהבו ג׳אז, ספרות ביטניקית והומור עוקצני. הם ניסו למכור שירים לזמרים אחרים, בלי הצלחה, ובסוף עברו ללוס אנג׳לס כדי לעבוד ככותבים בחברת תקליטים. שם הם הקימו להקה, קראו לה Steely Dan על שם חפץ מתוך ספר של ויליאם בורוז, והוציאו ב־1972 את Can't Buy a Thrill.''',
'''הצליל מלוטש, חכם ומתוחכם: רוק ופופ עם הרמוניות ואקורדים של ג׳אז, נגני אולפן מעולים, ומילים חידתיות על דמויות מפוקפקות. Do It Again, השיר הפותח, הוא גרוב לטיני איטי ומהפנט, עם סולו על סיטאר חשמלי וסולו של פייגן על אורגן קטן ומוזר. Reelin' in the Years הוא רוק מהיר עם סולו גיטרה מבריק, על מערכת יחסים שנגמרה. Dirty Work, ששר זמר אחר בלהקה, הוא שיר רך ועצוב על אהבה משפילה, ו־Midnight Cruiser הוא שיר מלנכולי על חבר ישן. בקר ופייגן כתבו את כל השירים יחד, ופייגן, שבהתחלה לא רצה לשיר, הפך בסוף לזמר הראשי ולקול המזוהה של הלהקה.''',
'''Do It Again ו־Reelin' in the Years הפכו ללהיטים גדולים באמריקה, והאלבום הציב את Steely Dan כאחת הלהקות המיוחדות של שנות השבעים. במשך השנים בקר ופייגן הפסיקו להופיע, והפכו לצמד אולפן שמקליט עם נגני הג׳אז והסשן הטובים בעולם, בדרך לאלבומים כמו Aja. הצליל שלהם השפיע על דורות של מפיקים ומוזיקאים.''',
'''שמעו את Do It Again עם אוזניות, והקשיבו לשני הסולואים באמצע. אחר כך את Reelin' in the Years, וחכו לגיטרה.''',
], [
('Do It Again', 'גרוב לטיני איטי ומהפנט, עם סולו על סיטאר חשמלי ואורגן מוזר.'),
("Reelin' in the Years", 'רוק מהיר עם סולו גיטרה מבריק, על אהבה שנגמרה.'),
('Dirty Work', 'שיר רך ועצוב על אהבה משפילה, בקול של זמר אחר מהלהקה.'),
])

add(246, [
'''אחרי After the Gold Rush (אלבום 186), ניל יאנג קנה חווה בצפון קליפורניה, ובאותה תקופה סבל מבעיות גב קשות שבגללן לא יכול היה לעמוד זמן רב עם גיטרה חשמלית כבדה. הוא נסע לנאשוויל, וגייס שם נגני אולפן מקומיים, שקרא להם The Stray Gators. Harvest יצא בתחילת 1972.''',
'''רוב השירים רכים, כפריים ואקוסטיים: גיטרה, מפוחית, פדל־סטיל ותופים שקטים. Heart of Gold, שבו ג׳יימס טיילור ולינדה רונסטדט שרים ברקע, הוא חיפוש פשוט אחר לב של זהב, ו־Old Man נכתב על המטפל הזקן של החווה שיאנג קנה, והשוואה בין חייו לחיי האיש הזקן. The Needle and the Damage Done, שהוקלט בהופעה, הוא שיר קצר וחשוף על חברים שמתו מהרואין. ושני שירים, A Man Needs a Maid ו־There's a World, מלווים בתזמורת הסימפונית של לונדון, מה שהוסיף להם דרמה. ג׳ק ניצ׳ה, שעבד גם עם הרולינג סטונס, עיבד את התזמורת, והמעבר בין השירים הקטנים לתזמורת הגדולה נותן לאלבום צבע מיוחד.''',
'''Heart of Gold הפך ללהיט היחיד של יאנג במקום הראשון באמריקה, ו־Harvest היה האלבום הנמכר ביותר באמריקה ב־1972. יאנג עצמו אמר מאוחר יותר שההצלחה הזאת שמה אותו "באמצע הכביש", ושהוא העדיף לנסוע לתעלה, והאלבומים הבאים שלו היו אפלים וקשים הרבה יותר. גם קרוסבי, סטילס ונאש מופיעים באלבום בקולות רקע, ובכך האלבום מחבר את יאנג שוב לחבריו הוותיקים (אלבום 184).''',
'''שמעו את Old Man ואחריו את The Needle and the Damage Done: שיר על זקנה ושיר על צעירים שלא יזדקנו. זה אלבום מצוין לנסיעה ארוכה בדרך כפרית.''',
], [
('Heart of Gold', 'חיפוש פשוט אחר לב של זהב, עם מפוחית וג׳יימס טיילור ברקע. מקום ראשון.'),
('Old Man', 'שיר על המטפל הזקן של החווה, ועל הדמיון בין צעיר לזקן.'),
('The Needle and the Damage Done', 'שיר קצר וחשוף מהופעה, רק גיטרה וקול, על חברים שמתו מהרואין.'),
])

add(247, [
'''קרטיס מייפילד היה הזמר והכותב של The Impressions, להקת סול משיקגו שכתבה בשנות השישים המנונים של תנועת זכויות האזרח, כמו People Get Ready. ב־1970 הוא יצא לקריירת סולו, וב־1972 כתב והקליט את הפסקול של Superfly, סרט על סוחר קוקאין בהארלם שרוצה לעשות עסקה אחרונה ולצאת. בזמן שהסרט הציג את הסוחר כגיבור, מייפילד כתב שירים שמראים את הצד השני: המכורים, המתים והמשפחות.''',
'''הצליל הוא פאנק וסול עשיר ומבריק: בס עמוק, גיטרת וואה־וואה, כלי הקשה לטיניים, כלי מיתר וכלי נשיפה, והקול הגבוה והרך של מייפילד, שנשמע עדין גם כשהוא מספר דברים קשים. Freddie's Dead מספר על מכור קטן שנהרג, ואף אחד לא מתאבל עליו, מעל גרוב שמח וקליט. Pusherman מתאר את סוחר הסמים מנקודת מבטו, ו־Little Child Runnin' Wild פותח את האלבום בסיפור על ילד שגדל ברחוב. שיר הנושא, Superfly, הוא גרוב מלא חיים עם כלי נשיפה.''',
'''Freddie's Dead ו־Superfly הגיעו לעשירייה הראשונה, והפסקול נמכר יותר מהסרט והגיע למקום הראשון באמריקה. יחד עם Shaft של אייזק הייז (אלבום 213) ו־What's Going On של מרווין גיי (אלבום 208), הוא נחשב לאחת היצירות הגדולות של הסול החברתי של שנות השבעים, והשפיע רבות על הפאנק ועל ההיפ הופ. מייפילד היה גם איש עסקים חכם, שהקים חברת תקליטים משלו ושמר על הזכויות לשירים שלו, דבר נדיר אצל אמנים שחורים באותם ימים.''',
'''שמעו את Freddie's Dead והקשיבו גם למילים: שיר קליט על מוות שאף אחד לא שם לב אליו. אחר כך את Pusherman, וחשבו על הניגוד בין הגרוב המגניב לבין הסיפור.''',
], [
("Freddie's Dead", 'גרוב קליט ושמח על מכור קטן שנהרג, ואף אחד לא מתאבל עליו.'),
('Pusherman', 'גרוב פאנקי ומהפנט מנקודת מבטו של סוחר הסמים, עם בס עמוק וכלי הקשה.'),
('Superfly', 'שיר הנושא: גרוב מלא חיים עם כלי נשיפה וקול גבוה ורך.'),
])

add(248, [
'''סלייד, ארבעה בחורים ממעמד הפועלים של וולברהמפטון באנגליה, התחילו כלהקת "סקינהדס" ונכשלו, עד שהמנהל שלהם, צ׳אס צ׳נדלר, שניהל קודם את ג׳ימי הנדריקס (אלבום 100), הציע להם להתלבש בצבעוניות מוגזמת ולכתוב שירים רועשים שקהל יכול לשיר. בתחילת שנות השבעים הם הפכו לאחת הלהקות הגדולות בבריטניה, עם שורת להיטים במקום הראשון. Slayed? יצא בסוף 1972.''',
'''סלייד היו מפורסמים בכתיב השגוי והמשעשע של שמות השירים שלהם, ובקול המחוספס והצועק של נודי הולדר. Mama Weer All Crazee Now הוא המנון רועש על מסיבה משוגעת, Gudbuy T'Jane הוא רוקנרול קליט עם מחיאות כפיים, ו־How D'You Ride פותח את האלבום בשירה כבדה ורועמת. יש גם גרסה ל־Move Over, שיר של ג׳ניס ג׳ופלין (אלבום 232). הצליל: גיטרות כבדות, תופים גדולים, פזמונים שנועדו לשירה של אלפי אנשים באצטדיון. דייב היל, הגיטריסט, הופיע בתלבושות מוגזמות ובתספורת משונה, והלהקה כולה נראתה כמו קרנבל רועש ושמח.''',
'''Slayed? הגיע למקום הראשון בבריטניה, ושני הלהיטים שבו היו במקום הראשון והשני במצעד הסינגלים. סלייד היו אחת הלהקות המצליחות בבריטניה בשנות השבעים, ושיר חג המולד שלהם, Merry Xmas Everybody, מושמע שם כל דצמבר עד היום. באמריקה הם התפרסמו פחות, אבל להקות כמו Quiet Riot וקיס שאבו מהם השראה, והקליטו את השירים שלהם. המילים הפשוטות, הפזמונים הרועשים והכתיב המצחיק הפכו אותם לחביבי הקהל הצעיר, שמילא את ההופעות שלהם וצעק כל מילה.''',
'''שמעו את Mama Weer All Crazee Now בקול רם, ונסו לא לשיר בפזמון. אחר כך השוו ל־Electric Warrior של T. Rex (אלבום 239): שני צדדים של הגלאם הבריטי, החושני והרועש.''',
], [
('Mama Weer All Crazee Now', 'המנון רועש על מסיבה משוגעת, עם הקול הצועק של נודי הולדר.'),
("Gudbuy T'Jane", 'רוקנרול קליט עם מחיאות כפיים, אחד הלהיטים הגדולים של הלהקה.'),
("How D'You Ride", 'הפותח: שירה כבדה ורועמת, גיטרות כבדות ופזמון שנועד לצעוק יחד.'),
])

add(249, [
'''באוגוסט 1972, כמה חודשים אחרי Machine Head (אלבום 242), דיפ פרפל יצאו לסיבוב הופעות ראשון ביפן, וחברת התקליטים היפנית ביקשה להקליט אותם לאלבום הופעה שייצא רק שם. הם הופיעו שלושה ערבים, באוסקה ובטוקיו, והטכנאי מרטין בירץ׳ הקליט הכול. כשהלהקה שמעה את התוצאה, הם החליטו להוציא אותה בכל העולם. Made in Japan יצא בסוף 1972.''',
'''זו להקה בשיא הכוח: כל חמשת הנגנים מאלתרים, מתחרים ומשוחחים. Highway Star פותח במהירות מטורפת, Child in Time (אלבום 188) נמתח לשתים־עשרה דקות של שקט, צעקות וסולו גיטרה, ו־Smoke on the Water נשמע כאן כבד וחי יותר מבאולפן. The Mule הוא סולו תופים של איאן פייס, Lazy נפתח באלתור ארוך של ג׳ון לורד על אורגן, ו־Space Truckin' נמתח לכמעט עשרים דקות של רעש, ניסויים ודו־קרב בין הגיטרה של ריצ׳י בלקמור לאורגן. בין השירים שומעים את הקהל היפני, מנומס ושקט יחסית בין השירים ונלהב מאוד בסופם, ואת איאן גילאן שמבקש עוד ווליום במוניטור.''',
'''Made in Japan נחשב לאחד מאלבומי ההופעה הגדולים של הרוק, יחד עם Live at Leeds (אלבום 193) ו־At Fillmore East (אלבום 214). הוא תיעד את ההרכב הקלאסי של דיפ פרפל כמה חודשים לפני שהתחיל להתפרק, והפך לתבנית של מה שאלבום הופעה של רוק כבד צריך להיות: ארוך, רועש ומלא וירטואוזיות.''',
'''שמעו את Child in Time כאן ובאלבום 188, אחד אחרי השני: אותו שיר, באולפן ועל הבמה. ואם יש לכם זמן, Space Truckin' הוא מסע של עשרים דקות.''',
], [
('Highway Star', 'הפותח: מהירות מטורפת, אורגן וגיטרה בשיא הכוח, כמו מכונית דוהרת.'),
('Child in Time', 'שתים־עשרה דקות של שקט, צעקות גבוהות וסולו גיטרה סוער.'),
('Smoke on the Water', 'השיר המפורסם בגרסה כבדה, ארוכה וחיה יותר מבאולפן.'),
])

add(250, [
'''אחרי Fragile (אלבום 218), יס רצו ליצור משהו גדול עוד יותר. ג׳ון אנדרסון קרא את "סידהרתא" של הרמן הסה, רומן על חיפוש רוחני, והלהקה בנתה סביב הרעיון יצירה של כמעט עשרים דקות. Close to the Edge יצא בספטמבר 1972, ויש בו שלוש יצירות בלבד: שיר הנושא, שממלא צד שלם, ושתי יצירות ארוכות בצד השני.''',
'''שיר הנושא נפתח בציוץ ציפורים ובזרימת מים, ואז מתפרץ בכאוס של גיטרה, בס, קלידים ותופים שנראים כאילו כל אחד מנגן משהו אחר, עד שהם מתחברים למלודיה. באמצע יש קטע שקט ומרחף, ואז סולו של ריק ווייקמן על עוגב כנסייה אמיתי, שמוביל לשיא גדול. And You and I מתחיל בגיטרה אקוסטית ומגיע לרגעים רחבים ורוחניים כמעט כמו מוזיקה של כנסייה, ו־Siberian Khatru הוא רוק קצבי ושמח עם גיטרה מהירה ומלודיות מסובכות. הלהקה ערכה את שיר הנושא מחלקים רבים שהוקלטו בנפרד, והמהנדס אדי אופורד חתך והדביק את הסרטים ביד, עבודה מדוקדקת של שבועות.''',
'''Close to the Edge נחשב בעיני רבים לשיא של יס ולאחד האלבומים החשובים של הרוק המתקדם. המתופף ביל ברופורד עזב מיד אחרי ההקלטות והצטרף לקינג קרימזון (אלבום 168). האלבום הראה כמה רחוק אפשר לקחת את הרוק לכיוון של מוזיקה קלאסית ורוחנית, בלי לאבד את האנרגיה. רבים מעריצי הרוק המתקדם בוחרים בו שוב ושוב כאלבום האהוב עליהם, ורבים מנגני הקלידים והגיטרה למדו אותו תו אחר תו.''',
'''תנו לשיר הנושא את כל עשרים הדקות שלו, באוזניות, בלי הפרעות. אם זה ארוך מדי, התחילו ב־And You and I, שעשר הדקות שלו עוברות מהר.''',
], [
('Close to the Edge', 'כמעט עשרים דקות: ציפורים, כאוס, שקט ועוגב כנסייה שמוביל לשיא.'),
('And You and I', 'גיטרה אקוסטית שמובילה לרגעים רחבים ורוחניים, כמעט כמו מוזיקה של כנסייה.'),
('Siberian Khatru', 'רוק קצבי ושמח עם גיטרה מהירה, מלודיות מסובכות והרמוניות.'),
])

add(251, [
'''אחרי שעזב את הוולווט אנדרגראונד (אלבומים 91, 104 ו־153), לו ריד הוציא אלבום סולו ראשון שכמעט לא נמכר. דייוויד בואי, שהעריץ את הוולווט (אלבום 240), הציע לעזור, ויחד עם הגיטריסט מיק רונסון הפיק את האלבום השני של ריד בלונדון. Transformer יצא בסוף 1972, בשיא תקופת הגלאם, עם עטיפה שבה ריד נראה כמו רוח רפאים עם איפור.''',
'''השירים מספרים על ניו יורק של אנדי וורהול: אמנים, שחקנים, דראג קווינס ודמויות מהשוליים. Walk on the Wild Side מתאר כמה מהם, כולל קנדי דרלינג (אלבום 153), בקול רגוע, מעל קו בס מפורסם שבו נגן אחד מנגן על קונטרבס ועל בס חשמלי יחד, סקסופון רך בסוף ומקהלה של "הבנות הצבעוניות". Perfect Day הוא שיר אהבה יפהפה ורגוע על יום מושלם בפארק, שיכול להישמע גם עצוב. Satellite of Love כולל קולות ליווי גבוהים של בואי, ו־Vicious ו־Andy's Chest הם שירים משעשעים וחצופים.''',
'''Walk on the Wild Side הפך ללהיט, למרות, או אולי בגלל, מילים שדיברו בגלוי על מין ועל זהות, והאלבום הפך את ריד לכוכב. Perfect Day זכה לחיים חדשים בשנות התשעים, אחרי שהופיע בסרט "טריינספוטינג". Transformer נחשב לאחד האלבומים החשובים של הגלאם ושל רוק ניו יורק. רונסון עיבד גם את כלי הקשת ואת כלי הנשיפה, וההפקה המלוטשת שלו ושל בואי הפכה את השירים של ריד לנגישים לקהל רחב.''',
'''שמעו את Walk on the Wild Side והקשיבו לבס בהתחלה ולסקסופון בסוף. ואז את Perfect Day, ותחליטו בעצמכם אם זה שיר שמח או עצוב.''',
], [
('Walk on the Wild Side', 'קו בס מפורסם, סקסופון ודמויות מהעולם של אנדי וורהול.'),
('Perfect Day', 'שיר אהבה יפהפה על יום מושלם, שיכול להישמע גם עצוב.'),
('Satellite of Love', 'שיר רך עם פסנתר וקולות ליווי גבוהים של דייוויד בואי.'),
])
